"use strict";
const K=window.GlassPhysicsKit, R=window.GlassPhysicsRegistry, META={"9.1": {"title": "Center Of Mass", "chapter": 9, "page": 1}, "9.2": {"title": "Newton\u2019S Second Law For A System Of Particles", "chapter": 9, "page": 7}, "9.3": {"title": "Linear Momentum", "chapter": 9, "page": 11}, "9.4": {"title": "Collision And Impulse", "chapter": 9, "page": 13}, "9.5": {"title": "Conservation Of Linear Momentum", "chapter": 9, "page": 17}, "9.6": {"title": "Momentum And Kinetic Energy In Collisions", "chapter": 9, "page": 20}, "9.7": {"title": "Elastic Collisions In One Dimension", "chapter": 9, "page": 24}, "9.8": {"title": "Collisions In Two Dimensions", "chapter": 9, "page": 27}, "9.9": {"title": "Systems With Varying Mass: A Rocket", "chapter": 9, "page": 28}, "10.1": {"title": "Rotational Variables", "chapter": 10, "page": 1}, "10.2": {"title": "Rotation With Constant Angular Acceleration", "chapter": 10, "page": 10}, "10.3": {"title": "Relating The Linear And Angular Variables", "chapter": 10, "page": 12}, "10.4": {"title": "Kinetic Energy Of Rotation", "chapter": 10, "page": 15}, "10.5": {"title": "Calculating The Rotational Inertia", "chapter": 10, "page": 17}, "10.6": {"title": "Torque", "chapter": 10, "page": 21}, "10.7": {"title": "Newton\u2019S Second Law For Rotation", "chapter": 10, "page": 23}, "10.8": {"title": "Work And Rotational Kinetic Energy", "chapter": 10, "page": 26}, "11.1": {"title": "Rolling As Translation And Rotation Combined", "chapter": 11, "page": 1}, "11.2": {"title": "Forces And Kinetic Energy Of Rolling", "chapter": 11, "page": 4}, "11.3": {"title": "The Yo-Yo", "chapter": 11, "page": 7}, "11.4": {"title": "Torque Revisited", "chapter": 11, "page": 8}, "11.5": {"title": "Angular Momentum", "chapter": 11, "page": 11}, "11.6": {"title": "Newton\u2019S Second Law In Angular Form", "chapter": 11, "page": 13}, "11.7": {"title": "Angular Momentum Of A Rigid Body", "chapter": 11, "page": 16}, "11.8": {"title": "Conservation Of Angular Momentum", "chapter": 11, "page": 18}, "11.9": {"title": "Precession Of A Gyroscope", "chapter": 11, "page": 23}, "12.1": {"title": "Equilibrium", "chapter": 12, "page": 1}, "12.2": {"title": "Some Examples Of Static Equilibrium", "chapter": 12, "page": 6}, "12.3": {"title": "Elasticity", "chapter": 12, "page": 12}, "13.1": {"title": "Newton\u2019S Law Of Gravitation", "chapter": 13, "page": 1}, "13.2": {"title": "Gravitation And The Principle Of Superposition", "chapter": 13, "page": 4}, "13.3": {"title": "Gravitation Near Earth\u2019S Surface", "chapter": 13, "page": 6}, "13.4": {"title": "Gravitation Inside Earth", "chapter": 13, "page": 9}, "13.5": {"title": "Gravitational Potential Energy", "chapter": 13, "page": 11}, "13.6": {"title": "Planets And Satellites: Kepler\u2019S Laws", "chapter": 13, "page": 15}, "13.7": {"title": "Satellites: Orbits And Energy", "chapter": 13, "page": 18}, "13.8": {"title": "Einstein And Gravitation", "chapter": 13, "page": 21}, "14.1": {"title": "Fluids, Density, And Pressure", "chapter": 14, "page": 1}, "14.2": {"title": "Fluids At Rest", "chapter": 14, "page": 3}, "14.3": {"title": "Measuring Pressure", "chapter": 14, "page": 7}, "14.4": {"title": "Pascal\u2019S Principle", "chapter": 14, "page": 8}, "14.5": {"title": "Archimedes\u2019 Principle", "chapter": 14, "page": 9}, "14.6": {"title": "The Equation Of Continuity", "chapter": 14, "page": 13}, "14.7": {"title": "Bernoulli\u2019S Equation", "chapter": 14, "page": 16}, "15.1": {"title": "Simple Harmonic Motion", "chapter": 15, "page": 1}, "15.2": {"title": "Energy In Simple Harmonic Motion", "chapter": 15, "page": 9}, "15.3": {"title": "An Angular Simple Harmonic Oscillator", "chapter": 15, "page": 11}, "15.4": {"title": "Pendulums, Circular Motion", "chapter": 15, "page": 12}, "15.5": {"title": "Damped Simple Harmonic Motion", "chapter": 15, "page": 18}, "15.6": {"title": "Forced Oscillations And Resonance", "chapter": 15, "page": 20}, "16.1": {"title": "Transverse Waves", "chapter": 16, "page": 1}, "16.2": {"title": "Wave Speed On A Stretched String", "chapter": 16, "page": 9}, "16.3": {"title": "Energy And Power Of A Wave Traveling Along A String", "chapter": 16, "page": 11}, "16.4": {"title": "The Wave Equation", "chapter": 16, "page": 13}, "16.5": {"title": "Interference Of Waves", "chapter": 16, "page": 15}, "16.6": {"title": "Phasors", "chapter": 16, "page": 19}, "16.7": {"title": "Standing Waves And Resonance", "chapter": 16, "page": 22}, "17.1": {"title": "Speed Of Sound", "chapter": 17, "page": 1}, "17.2": {"title": "Traveling Sound Waves", "chapter": 17, "page": 4}, "17.3": {"title": "Interference", "chapter": 17, "page": 7}, "17.4": {"title": "Intensity And Sound Level", "chapter": 17, "page": 10}, "17.5": {"title": "Sources Of Musical Sound", "chapter": 17, "page": 14}, "17.6": {"title": "Beats", "chapter": 17, "page": 18}, "17.7": {"title": "The Doppler Effect", "chapter": 17, "page": 20}, "17.8": {"title": "Supersonic Speeds, Shock Waves", "chapter": 17, "page": 25}};
const g=9.81,pi=Math.PI,TAU=2*pi,fmt=K.fmt,rad=x=>x*pi/180;
const slider=(key,label,min,max,step,value,unit='')=>({key,label,min,max,step,value,unit});
const select=(key,label,value,options)=>({key,label,value,options:options.map(([value,label])=>({value,label}))});
const read=(label,value,unit='')=>({label,value,unit});
const text=(x,y,t,k='ink',size=17)=>K.text(x,y,t,k,size);
const note=t=>text(480,480,t,'muted',15);
const box=(x,y,w,h,k='surface')=>K.rect(x,y,w,h,k);
const wheel=(cx,cy,r,theta,kind='coral')=>K.circle(cx,cy,r,kind,.18)+K.path(`M${cx+r},${cy}A${r},${r} 0 1 0 ${cx-r},${cy}A${r},${r} 0 1 0 ${cx+r},${cy}`,kind,4)+[0,pi/2,pi,3*pi/2].map(a=>K.line(cx,cy,cx+r*Math.cos(theta+a),cy-r*Math.sin(theta+a),kind,2)).join('')+K.circle(cx,cy,5,'wire');
const spring=(x1,x2,y)=>K.path(`M${x1},${y} `+Array.from({length:21},(_,i)=>`L${x1+(x2-x1)*(i+1)/22},${y+(i%2?12:-12)}`).join(' ')+`L${x2},${y}`,'wire',3);
const cart=(x,y,m,label,kind='coral')=>box(x-27-3*m,y-35,54+6*m,35,kind)+K.circle(x-22,y+7,9,'wire')+K.circle(x+22,y+7,9,'wire')+text(x,y-48,label,kind);
const diskPoint=(cx,cy,r,a)=>[cx+r*Math.cos(a),cy-r*Math.sin(a)];
const step=(title,why,equation,visual)=>({title,why,equation,visual});
function add(id,o){const meta=META[id];if(!meta)throw Error(id);o.title=o.title||meta.title;o.source={section:id,file:`books/physics/chapter-${String(meta.chapter).padStart(2,'0')}.pdf`,pages:[meta.page,meta.page+1],note:o.sourceNote+' Original adjustable teaching example, not a transcription or an exact simulation of every linked exercise.'};delete o.sourceNote;o.animation=o.animation||{label:'Run experiment',kind:'physical',duration:8};R[id]=o;}
const target=(prompt,answer,unit,steps)=>({prompt,answer,unit,steps,tolerance:Math.max(1e-8,Math.abs(answer)*.005)});
const standard=(s,keys)=>keys.map(k=>`${k} = ${fmt(s[k])}`).join(', ');
// Center of mass, momentum, impact and recoil: signed rightward convention.
add('9.1',{title:'Balance two masses at their center of mass',intro:'Move the masses and change their sizes. The support follows the weighted balance point, not the midpoint.',controls:[slider('m1','Left mass',1,6,.5,2,'kg'),slider('m2','Right mass',1,6,.5,4,'kg'),slider('d','Separation',1,5,.1,3,'m')],compute:s=>({x:s.m2*s.d/(s.m1+s.m2),readouts:[read('Center of mass from left',s.m2*s.d/(s.m1+s.m2),'m')]}),scene:(s,m,t,stage)=>{const x=200+110*m.x;return (stage===1?K.circle(200+110*s.d,270,50,'coral',.12):stage===2?K.circle(x,310,40,'aqua',.2):'')+ K.line(200,295,200+110*s.d,295,'wire',8)+K.circle(200,270,14+4*s.m1,'coral')+K.circle(200+110*s.d,270,14+4*s.m2,'aqua')+K.path(`M${x-25},350L${x},300L${x+25},350Z`,'coral',3,'coral')+text(200,205,`${s.m1} kg`)+text(200+110*s.d,205,`${s.m2} kg`)+text(x,390,`Balance point: ${fmt(m.x)} m`)+note('Original 1D two-point-mass balance; beam has negligible mass.');},steps:[step('Choose a reference','Place the left mass at x = 0. Each position is measured from this same origin.','x₁ = 0; x₂ = d','The two masses sit on a massless beam.'),step('Weight each position','A heavier mass contributes more strongly to the average.','x_cm = (m₁x₁ + m₂x₂)/(m₁ + m₂)','The coral support moves toward the heavier mass.'),step('Check the torques','At the center of mass the two weights have equal opposing moments.','m₁gx_cm = m₂g(d − x_cm)','Equal moments explain why the beam balances.')],target:(s,m)=>target(`Find the center of mass in metres from the left mass. ${standard(s,['m1','m2','d'])}.`,m.x,'m',['Set x₁ = 0 and x₂ = d.',`x_cm = (${s.m2} × ${s.d})/(${s.m1} + ${s.m2}) = ${fmt(m.x)} m.`]),animation:{label:'Inspect balance',kind:'construction',duration:6},sourceNote:'Inspected §9.1 center-of-mass definition and two-particle illustrations; ignores beam mass.'});
add('9.2',{title:'Push a two-cart system',intro:'A spring transmits internal forces. Only the external push accelerates the total center of mass.',controls:[slider('m1','First cart mass',1,5,.5,2,'kg'),slider('m2','Second cart mass',1,5,.5,3,'kg'),slider('F','External force',1,10,.5,4,'N')],compute:s=>({a:s.F/(s.m1+s.m2),x:.5*s.F/(s.m1+s.m2)*s.time*s.time,readouts:[read('Center-of-mass acceleration',s.F/(s.m1+s.m2),'m/s²'),read('External force',s.F,'N')]}),scene:(s,m)=>{const x=180+12*m.x;return K.line(80,348,880,348)+cart(x,330,s.m1,'Cart 1')+spring(x+50,x+150,310)+cart(x+200,330,s.m2,'Cart 2','aqua')+K.arrow(x-65,290,x-65+8*s.F,290)+K.arrow(x+65,265,x+130,265,'aqua')+K.arrow(x+135,280,x+70,280,'aqua')+text(480,100,'Internal forces cancel in the system sum')+text(480,410,`x_cm displacement = ${fmt(m.x)} m`)+note('Frictionless track. Spring extension is schematic; carts treated as one coupled body.');},steps:[step('Draw the system','Include both carts so the spring forces are internal.','M = m₁ + m₂','The two aqua arrows are the internal action–reaction pair.'),step('Add external forces','Internal forces cancel pairwise; the applied force remains.','F_ext = M a_cm','The coral arrow is the only horizontal external force.'),step('Predict motion','With a constant force and zero initial speed, the center of mass accelerates uniformly.','Δx_cm = ½a_cm t²','Both carts advance as the total mass increases or decreases.')],target:(s,m)=>target(`For coupled carts starting from rest, find a_cm. ${standard(s,['m1','m2','F'])}.`,m.a,'m/s²',[`M = ${s.m1+s.m2} kg.`,`a_cm = ${s.F}/${s.m1+s.m2} = ${fmt(m.a)} m/s².`]),animation:{label:'Push carts',kind:'physical',duration:4},sourceNote:'Inspected §9.2 F_net = M a_cm and internal/external force discussion; rigid-coupling approximation.'});
add('9.3',{title:'See the direction of momentum',intro:'Change mass and signed velocity. The arrow follows momentum; moving left gives negative momentum.',controls:[slider('m','Particle mass',1,6,.5,3,'kg'),slider('v','Signed velocity',-3,3,.25,2,'m/s')],compute:s=>({p:s.m*s.v,x:480+25*s.v*s.time,readouts:[read('Signed momentum',s.m*s.v,'kg m/s')]}),scene:(s,m)=>K.line(100,350,860,350)+K.circle(m.x,300,15+4*s.m,'coral')+K.arrow(m.x,235,m.x+8*m.p,235)+text(m.x,190,`p = ${fmt(m.p)} kg m/s`)+text(480,410,'Positive direction →')+note('No net force: constant velocity and momentum; fixed 25 px per metre.'),steps:[step('Momentum is a vector','The mass is positive, so momentum has the velocity direction.','p = mv','The arrow reverses when the velocity crosses zero.'),step('Scale mass and speed','Doubling either mass or speed doubles momentum.','|p| = m|v|','Mass changes the particle size and momentum arrow.'),step('Use Newton’s law','If no net force acts, momentum stays constant.','F_net = dp/dt = 0','Uniform straight motion leaves the arrow unchanged.')],target:(s,m)=>target(`Find signed momentum with positive to the right. ${standard(s,['m','v'])}.`,m.p,'kg m/s',['Use the velocity sign with right positive.',`p = mv = ${s.m} × (${s.v}) = ${fmt(m.p)} kg m/s.`]),animation:{label:'Move particle',kind:'physical',duration:3},sourceNote:'Inspected §9.3 vector momentum and time derivative; force-free one-dimensional particle.'});
add('9.4',{title:'Deliver an impulse to a cart',intro:'A constant force acts for a limited contact interval. Watch the cart gain momentum during contact, then coast.',controls:[slider('m','Cart mass',1,5,.5,2,'kg'),slider('F','Contact force',1,10,.5,4,'N'),slider('dt','Contact duration',.2,2,.1,1,'s')],compute:s=>{const t=Math.min(s.time,s.dt),v=s.F*t/s.m;return {t,v,J:s.F*t,x:.5*s.F/s.m*t*t+v*Math.max(0,s.time-s.dt),readouts:[read('Delivered impulse',s.F*t,'N s'),read('Cart velocity',v,'m/s')]};},scene:(s,m)=>{const x=180+12*m.x;return K.line(80,350,880,350)+cart(x,330,s.m,'Cart')+(s.time<s.dt?K.arrow(x-100,230,x-100+9*s.F,230):text(x,250,'Contact ended','muted'))+box(100,100,260,30)+box(100,100,260*m.t/s.dt,30,'coral')+text(230,165,`Contact: ${fmt(m.t)} / ${s.dt} s`)+note('Rectangular force pulse, negligible friction; impulse is accumulated force × time.');},steps:[step('Identify contact time','The net force acts only while the bumper touches the cart.','0 ≤ t_contact ≤ Δt','The progress strip marks the duration of contact.'),step('Accumulate impulse','A constant force supplies the same extra momentum each second.','J = F Δt = Δp','The cart accelerates only while the force arrow is present.'),step('Convert to velocity','Divide the momentum change by mass; afterward no horizontal force acts.','v_final = F Δt/m','The final speed persists after separation.')],target:(s,m)=>target(`Find the final speed after the entire force pulse, regardless of displayed time. ${standard(s,['m','F','dt'])}.`,s.F*s.dt/s.m,'m/s',[`J = ${s.F} × ${s.dt} = ${fmt(s.F*s.dt)} N s.`,`v_f = J/m = ${fmt(s.F*s.dt/s.m)} m/s.`]),animation:{label:'Apply impulse',kind:'physical',duration:3},sourceNote:'Inspected §9.4 impulse integral and constant average-force result; ideal rectangular pulse from rest.'});
add('9.5',{title:'Two skaters push apart',intro:'A spring gives the skaters equal and opposite impulses. The lighter skater recoils faster, while the center of mass stays fixed.',controls:[slider('m1','Left skater mass',30,90,5,50,'kg'),slider('m2','Right skater mass',30,90,5,75,'kg'),slider('J','Push impulse magnitude',10,60,5,30,'N s')],compute:s=>({v1:-s.J/s.m1,v2:s.J/s.m2,readouts:[read('Left velocity',-s.J/s.m1,'m/s'),read('Right velocity',s.J/s.m2,'m/s'),read('Total momentum',0,'kg m/s')]}),scene:(s,m)=>{const x1=430+32*m.v1*s.time,x2=530+32*m.v2*s.time;return K.line(80,370,880,370)+cart(x1,350,s.m1/15,'Left')+cart(x2,350,s.m2/15,'Right','aqua')+K.arrow(x1,260,x1+60*m.v1,260)+K.arrow(x2,260,x2+60*m.v2,260,'aqua')+text(480,130,'Total momentum: zero before and after')+note('Animation starts just after the brief push. External horizontal force is zero.');},steps:[step('Choose both skaters','The push is internal and there is no external horizontal impulse.','P_initial = 0','The ice track supplies no horizontal friction.'),step('Use equal opposite impulses','Newton’s third law gives opposite momentum changes.','p₁ = −J; p₂ = +J','Oppositely directed arrows show the recoil.'),step('Divide by each mass','The same momentum magnitude creates different speeds for different masses.','v₁ = −J/m₁; v₂ = J/m₂','The lighter skater travels farther per second.')],target:(s,m)=>target(`Find the left skater’s signed velocity after the push. ${standard(s,['m1','m2','J'])}; right is positive.`,m.v1,'m/s',[`Δp_left = −${s.J} N s.`,`v_left = −${s.J}/${s.m1} = ${fmt(m.v1)} m/s.`]),animation:{label:'Release skaters',kind:'physical',duration:4},sourceNote:'Inspected §9.5 conservation for isolated systems; modeled instantaneous equal/opposite internal impulse.'});
function collision(id,elastic){add(id,{title:elastic?'Bounce carts elastically':'Compare energy loss in a collision',intro:elastic?'An elastic collision conserves both momentum and kinetic energy. Mass ratio decides whether the incoming cart rebounds.':'Momentum remains conserved while restitution sets how much kinetic energy becomes internal energy.',controls:[slider('m1','Incoming mass',1,5,.5,2,'kg'),slider('m2','Target mass',1,5,.5,3,'kg'),slider('u','Incoming speed',.5,3,.25,2,'m/s'),...(elastic?[]:[slider('e','Restitution',0,1,.1,.4)])],compute:s=>{const e=elastic?1:s.e,v1=(s.m1-e*s.m2)/(s.m1+s.m2)*s.u,v2=(1+e)*s.m1/(s.m1+s.m2)*s.u;return{v1,v2,loss:elastic?0:Math.max(0,.5*s.m1*s.u*s.u-.5*s.m1*v1*v1-.5*s.m2*v2*v2),readouts:[read('Incoming cart after',v1,'m/s'),read('Target after',v2,'m/s'),read('Kinetic energy transferred internally',elastic?0:Math.max(0,.5*s.m1*s.u*s.u-.5*s.m1*v1*v1-.5*s.m2*v2*v2),'J')]};},scene:(s,m)=>{const hit=1,post=Math.max(0,s.time-hit),x1=s.time<=hit?390-32*s.u*(hit-s.time):390+32*m.v1*post,x2=390+54+3*(s.m1+s.m2)+32*m.v2*post;return K.line(80,350,890,350)+cart(x1,330,s.m1,'Incoming')+cart(x2,330,s.m2,'Target','aqua')+K.arrow(x1,250,x1+24*(s.time<hit?s.u:m.v1),250)+K.arrow(x2,220,x2+24*(s.time<hit?0:m.v2),220,'aqua')+text(480,110,s.time<hit?'Before impact':'After impact')+text(480,420,(s.time<hit?'Predicted collision loss = ':'Collision loss = ')+fmt(m.loss)+' J')+note('Ideal instantaneous impact at t = 1 s. Cart widths schematic; speed scale fixed.');},steps:[step('Keep momentum','The track supplies no horizontal impulse during impact.','m₁u = m₁v₁ + m₂v₂','The target begins at rest.'),step(elastic?'Require elastic rebound':'Choose restitution',elastic?'A perfectly elastic collision also conserves total kinetic energy.':'Restitution compares separation speed with approach speed.',elastic?'K_initial = K_final':'v₂ − v₁ = e u','Watch whether the first cart continues or reverses.'),step('Solve both constraints','Use momentum and relative speed together; any lost kinetic energy becomes internal energy.','v₁ = (m₁ − e m₂)u/(m₁ + m₂); v₂ = (1 + e)m₁u/(m₁ + m₂)','The two carts move at their separately predicted speeds.')],target:(s,m)=>target(`Find the target cart’s post-collision speed. ${standard(s,['m1','m2','u'])}; e = ${elastic?1:s.e}; target initially at rest.`,m.v2,'m/s',[`Apply momentum conservation and v₂ − v₁ = ${elastic?1:s.e}u.`,`v₂ = (1 + e)m₁u/(m₁ + m₂) = ${fmt(m.v2)} m/s.`]),animation:{label:'Collide carts',kind:'physical',duration:3},sourceNote:`Inspected §${id} isolated collisions and ${elastic?'elastic final-speed equations':'inelastic energy and momentum distinction'}; stationary target, instantaneous 1D contact.`});}
collision('9.6',false);collision('9.7',true);
add('9.8',{title:'Scatter two equal-mass balls',intro:'An incoming ball strikes an identical stationary target. In an elastic glancing collision their outgoing velocities are perpendicular. The common mass cancels from speeds, but not momentum or energy.',controls:[slider('u','Incoming speed',.5,3,.25,2,'m/s'),slider('angle','Projectile deflection',10,80,5,35,'°'),slider('mass','Each ball mass',.5,3,.25,1,'kg')],compute:s=>{const a=rad(s.angle),v1=s.u*Math.cos(a),v2=s.u*Math.sin(a);return{a,v1,v2,p1x:s.mass*v1*Math.cos(a),p1y:s.mass*v1*Math.sin(a),p2x:s.mass*v2*Math.sin(a),p2y:-s.mass*v2*Math.cos(a),readouts:[read('Projectile speed after',v1,'m/s'),read('Target speed after',v2,'m/s'),read('Initial total momentum',s.mass*s.u,'kg m/s'),read('Total kinetic energy',.5*s.mass*s.u*s.u,'J')]};},scene:(s,m)=>{const pa=(...p)=>K.arrow(...p).replace('<path ','<path stroke="'+K.color('paper')+'" stroke-width="2.5" stroke-linejoin="round" paint-order="stroke fill" ');const post=s.time>=1,dt=Math.max(0,s.time-1),sc=45,x1=post?450+sc*m.v1*Math.cos(m.a)*dt:450-sc*s.u*(1-s.time),y1=270-sc*m.v1*Math.sin(m.a)*dt,x2=450+sc*m.v2*Math.sin(m.a)*dt,y2=270+sc*m.v2*Math.cos(m.a)*dt;return K.line(120,270,450,270,'line',2)+K.circle(x1,y1,15+3*s.mass,'coral')+K.circle(x2,post?y2:270,15+3*s.mass,'aqua')+(post?pa(450,270,450+30*m.p1x,270-30*m.p1y)+pa(450,270,450+30*m.p2x,270-30*m.p2y,'aqua'):pa(x1,215,x1+30*s.mass*s.u,215))+text(480,70,post?'After impact: outgoing momenta':'Before impact: incoming momentum')+text(480,100,'Equal masses; elastic; target initially at rest','muted',15)+text(480,450,'Fixed scales: motion 45 px/m; momentum arrows 30 px/(kg m/s).','muted',14)+note('Common mass cancels from speeds, not momentum or energy. Point-particle impact at t = 1 s.');},steps:[step('Resolve the vectors','Momentum must balance independently along horizontal and vertical directions.','m u = p₁x + p₂x; 0 = p₁y + p₂y','Outgoing momentum arrows add to the incident momentum; their vertical components cancel.'),step('Use elastic energy','The stationary target and equal masses simplify kinetic energy conservation.','u² = v₁² + v₂²','For equal masses, the momentum triangle has the same right angle as the velocity triangle.'),step('Solve the speeds','The projectile deflects by θ, so its speed is the incoming speed projected on that direction.','v₁ = u cos θ; v₂ = u sin θ','The aqua target travels at angle θ − 90°.')],target:(s,m)=>target(`Equal-mass elastic collision: incident speed ${s.u} m/s, projectile deflection ${s.angle}°. Find the initially stationary target’s final speed.`,m.v2,'m/s',[`v_target = u sin θ = ${s.u} sin(${s.angle}°).`,`v_target = ${fmt(m.v2)} m/s.`]),animation:{label:'Scatter balls',kind:'physical',duration:3},sourceNote:'Inspected §9.8 two-dimensional momentum components and elastic energy; equal-mass special case only; fixed motion/momentum scales and honest pre-/post-impact arrows.'});
add('9.9',{title:'Burn fuel and accelerate a rocket',intro:'A rocket moves by expelling mass backward. More fuel increases the logarithmic speed gain, while faster exhaust transfers more momentum per kilogram.',controls:[slider('dry','Dry mass',100,400,25,200,'kg'),slider('fuel','Initial fuel',50,400,25,200,'kg'),slider('exhaust','Exhaust speed relative to rocket',100,800,50,400,'m/s')],compute:s=>{const fraction=s.time/8,M=s.dry+s.fuel*(1-fraction),v=s.exhaust*Math.log((s.dry+s.fuel)/M);return{M,v,fraction,readouts:[read('Remaining mass',M,'kg'),read('Rocket speed',v,'m/s'),read('Burnout speed',s.exhaust*Math.log((s.dry+s.fuel)/s.dry),'m/s')]};},scene:(s,m,t)=>{const x=360+220*m.v/1100;return K.path(`M${x-50},225L${x+75},225L${x+115},270L${x+75},315L${x-50},315Z`,'wire',3,'surface')+box(x-40,240,105*(1-m.fraction),60,'coral')+text(x+25,365,`${fmt(m.M)} kg`)+Array.from({length:12},(_,i)=>K.circle(x-60-((t*35*s.exhaust/400+i*21)%190),245+(i%3)*25,3,'aqua')).join('')+K.arrow(x+120,270,x+120+80*m.v/1300,270)+text(480,100,'Fuel leaves backward relative to the rocket')+note('Space rocket, no gravity or drag. Position and exhaust markers are schematic, not integrated distance.');},steps:[step('Choose the rocket plus exhaust','Momentum is conserved for the full isolated system. The rocket alone loses mass.','M dv = −v_rel dM','The coral fuel reservoir empties as aqua exhaust leaves.'),step('Integrate changing mass','Each kilogram ejected acts on a lighter remaining rocket.','Δv = v_rel ln(M_initial/M)','The rocket’s speed grows nonlinearly during a constant mass-flow burn.'),step('Check the limits','No fuel gives no gain; doubling exhaust speed doubles the gain at fixed mass ratio.','v_burnout = v_rel ln((m_dry + m_fuel)/m_dry)','Burnout leaves the dry mass, not zero mass.')],target:(s,m)=>target(`Find speed gain after all fuel is expelled: dry mass ${s.dry} kg, fuel ${s.fuel} kg, relative exhaust speed ${s.exhaust} m/s, initial speed zero.`,s.exhaust*Math.log((s.dry+s.fuel)/s.dry),'m/s',[`M_i/M_f = ${s.dry+s.fuel}/${s.dry}.`,`Δv = ${s.exhaust} ln(${fmt((s.dry+s.fuel)/s.dry)}) = ${fmt(s.exhaust*Math.log((s.dry+s.fuel)/s.dry))} m/s.`]),animation:{label:'Burn fuel',kind:'carriers',duration:8},sourceNote:'Inspected §9.9 first and second rocket equations; constant exhaust speed, no external forces; burn fraction uses illustration time.'});
// Rotation: consistent CCW-positive convention, radians in state equations.
const rotBase=[slider('radius','Radius',.2,.8,.05,.5,'m'),slider('omega','Initial angular speed',0,4,.25,1,'rad/s')];
function rotorScene(s,m,t,speedScale=20){
 const cx=480,cy=280,r=150*s.radius/.8,a=m.theta||0,p=diskPoint(cx,cy,r,a),v=s.radius*(m.omega||0);
 const arrow=(...args)=>K.arrow(...args).replace('<path ','<path stroke="'+K.color('paper')+'" stroke-width="2.5" stroke-linejoin="round" paint-order="stroke fill" ');
 let body=(s.mass&&s.beta!==1?K.circle(cx,cy,r*.9,'coral',.06+.35*s.mass/6):'')+wheel(cx,cy,r,a);
 if(s.beta===1){body+=K.circle(cx,cy,r*.82,'paper')+K.line(cx,cy,...p,'coral',2)+K.circle(cx,cy,5,'wire')+Array.from({length:Math.round(4*s.mass)},(_,i)=>{const q=diskPoint(cx,cy,r,TAU*i/Math.round(4*s.mass)+a);return K.circle(...q,3,'coral');}).join('');}
 const direction=Math.sign(v),vx=p[0]-14*direction*Math.sin(a),vy=p[1]-14*direction*Math.cos(a);
 return body+K.circle(...p,10,'aqua')+(Math.abs(v)>1e-10?K.line(p[0],p[1],vx,vy,'line',1)+arrow(vx,vy,vx-Math.sin(a)*speedScale*v,vy-Math.cos(a)*speedScale*v,'aqua'):'')+text(480,75,`θ = ${fmt(m.theta||0)} rad; ω = ${fmt(m.omega||0)} rad/s`)+K.line(cx,cy,cx+r,cy,'line',2)+text(760,325,`R = ${s.radius} m`)+text(160,410,`v = Rω = ${fmt(v)} m/s`,'aqua',15)+text(160,435,`Velocity: ${speedScale} px/(m/s)`,'muted',13)+note(m.caption||'Vector origins shifted off the rim marker for visibility; true lengths, no capping. CCW positive.');
}
const rotationConfigs={
'10.1':{title:'Mark the angular position of a wheel',intro:'A spoke turns about a fixed axle. Angle tracks revolutions even after the visible spoke returns to its starting direction.',controls:[...rotBase,slider('theta0','Starting angle',0,180,15,30,'°')],calc:s=>({theta:rad(s.theta0)+s.omega*s.time,omega:s.omega,value:rad(s.theta0)+s.omega*s.time,unit:'rad',label:'Angular position'}),steps:[step('Fix a reference','Measure angular position from the stationary horizontal line, counterclockwise positive.','θ = θ₀ + ωt','The coral spoke rotates relative to the gray reference.'),step('Use radians','An arc length s at radius r subtends angle s/r.','θ = s/r','Changing radius changes the rim, not the common angle.'),step('Keep revolution count','The displayed angle is not reduced modulo one revolution.','1 revolution = 2π rad','The spoke can return to the same direction with a different cumulative angle.')],answer:(s,m)=>target(`At displayed model time t = ${fmt(s.time)} s, find θ. Initial angle ${s.theta0}°, ω = ${s.omega} rad/s.`,m.theta,'rad',[`θ₀ = ${s.theta0}π/180 = ${fmt(rad(s.theta0))} rad.`,`θ = θ₀ + ωt = ${fmt(m.theta)} rad.`])},
'10.2':{title:'Spin up a wheel with constant angular acceleration',intro:'Watch equal time intervals produce increasing angular displacements as a steady angular acceleration changes the speed.',controls:[...rotBase,slider('alpha','Angular acceleration',-.3,.8,.1,.3,'rad/s²')],calc:s=>({theta:s.omega*s.time+.5*s.alpha*s.time*s.time,omega:s.omega+s.alpha*s.time,value:s.omega+s.alpha*s.time,unit:'rad/s',label:'Angular speed'}),steps:[step('State the assumption','Angular acceleration is constant throughout this ideal run.','α = dω/dt = constant','A positive acceleration spins the wheel up counterclockwise.'),step('Find angular speed','Integrate acceleration once. Negative acceleration can eventually reverse direction.','ω = ω₀ + αt','The signed speed is shown above the axle.'),step('Find accumulated angle','Integrate the changing angular speed, retaining the one-half factor.','θ − θ₀ = ω₀t + ½αt²','Spoke position accumulates the complete speed history.')],answer:(s,m)=>target(`Find signed ω at t = ${fmt(s.time)} s, ω₀ = ${s.omega} rad/s, α = ${s.alpha} rad/s².`,m.omega,'rad/s',['Constant angular acceleration changes speed by Δω = αt.',`ω = ${s.omega} + (${s.alpha})(${fmt(s.time)}) = ${fmt(m.omega)} rad/s.`])},
'10.3':{title:'Compare rim speed and acceleration',intro:'The same angular speed produces a greater linear speed at a larger radius. Separate tangential acceleration from the inward turning acceleration.',controls:[...rotBase,slider('alpha','Angular acceleration',0,.5,.05,.2,'rad/s²')],calc:s=>{const w=s.omega+s.alpha*s.time;return{theta:s.omega*s.time+.5*s.alpha*s.time*s.time,omega:w,v:w*s.radius,ar:w*w*s.radius,at:s.alpha*s.radius,value:w*w*s.radius,unit:'m/s²',label:'Radial acceleration'};},steps:[step('Relate distance and angle','Every point shares the same angle but a larger radius sweeps more distance.','s = rθ; v = rω','The rim point and aqua velocity move around the axle.'),step('Turn the velocity','Even at constant speed the velocity direction changes, giving inward acceleration.','a_radial = ω²r','The coral arrow points toward the axle.'),step('Change the speed','Angular acceleration also gives a perpendicular tangential component.','a_tangential = αr','The separate aqua component lies along the tangent.')],answer:(s,m)=>target(`Find radial acceleration at displayed t = ${fmt(s.time)} s, R = ${s.radius} m, ω₀ = ${s.omega} rad/s, α = ${s.alpha} rad/s².`,m.ar,'m/s²',[`ω = ω₀ + αt = ${fmt(m.omega)} rad/s.`,`a_r = ω²R = ${fmt(m.ar)} m/s².`])},
'10.4':{title:'Store energy in a rotating flywheel',intro:'A rim concentrates mass farther from the axle than a solid disk. Compare the kinetic energy at the same mass, radius and speed.',controls:[...rotBase,slider('mass','Flywheel mass',1,6,.5,3,'kg'),select('beta','Mass distribution',.5,[[.5,'Solid disk'],[1,'Thin rim']])],calc:s=>({theta:s.omega*s.time,omega:s.omega,I:s.beta*s.mass*s.radius*s.radius,value:.5*s.beta*s.mass*s.radius*s.radius*s.omega*s.omega,unit:'J',label:'Rotational kinetic energy'}),steps:[step('Locate the mass','Mass farther from the axle contributes more strongly to inertia.','I = βMR²','The solid disk and thin rim have different radial mass distributions.'),step('Add particle energies','Each particle moves at v = rω; summing ½mv² gives rotational energy.','K = ½Iω²','The wheel shares one angular speed; darker fill or more rim markers represents added mass.'),step('Compare distributions','At fixed mass, radius and speed a thin rim stores twice the energy of a uniform disk.','I_disk = ½MR²; I_rim = MR²','Use the distribution selector to change the actual wheel.')],answer:(s,m)=>target(`Find K for β = ${s.beta}, M = ${s.mass} kg, R = ${s.radius} m, ω = ${s.omega} rad/s.`,m.value,'J',[`I = βMR² = ${fmt(m.I)} kg m².`,`K = ½Iω² = ${fmt(m.value)} J.`])},
'10.7':{title:'Apply a torque to a flywheel',intro:'A tangential pull spins a solid disk. At fixed torque, a greater rotational inertia makes the spin grow more slowly.',controls:[slider('radius','Disk radius',.2,.7,.05,.4,'m'),slider('mass','Disk mass',1,6,.5,3,'kg'),slider('force','Tangential pull',.2,2,.1,1,'N')],calc:s=>{const I=.5*s.mass*s.radius*s.radius,torque=s.force*s.radius,alpha=torque/I;return{I,torque,alpha,theta:.5*alpha*s.time*s.time,omega:alpha*s.time,value:alpha,unit:'rad/s²',label:'Angular acceleration'};},steps:[step('Find the applied torque','A tangential force has the full radius as its lever arm.','τ = RF','The force arrow is tangent to the rim.'),step('Compute the inertia','For a uniform disk the mass is distributed throughout the radius.','I = ½MR²','Increasing the radius increases inertia quadratically.'),step('Apply rotational Newton’s law','Torque changes angular speed; it does not directly set angular speed.','α = τ/I','From rest the wheel spins up rather than jumping to a fixed speed.')],answer:(s,m)=>target(`Find α for a uniform disk: M = ${s.mass} kg, R = ${s.radius} m, tangential F = ${s.force} N.`,m.alpha,'rad/s²',[`τ = RF = ${fmt(m.torque)} N m; I = ½MR² = ${fmt(m.I)} kg m².`,`α = τ/I = ${fmt(m.alpha)} rad/s².`])},
'10.8':{title:'Do work by turning a flywheel',intro:'The pull does work through an angular displacement. The increase of rotational kinetic energy equals that work.',controls:[slider('radius','Flywheel radius',.2,.7,.05,.4,'m'),slider('mass','Disk mass',1,6,.5,3,'kg'),slider('torque','Applied torque',.1,1,.1,.4,'N m')],calc:s=>{const I=.5*s.mass*s.radius*s.radius,a=s.torque/I,theta=.5*a*s.time*s.time,w=a*s.time;return{I,theta,omega:w,work:s.torque*theta,power:s.torque*w,value:s.torque*theta,unit:'J',label:'Work supplied'};},steps:[step('Rotate through an angle','Torque supplies work through angle, just as force supplies work through distance.','dW = τ dθ','The spoke tracks the angle through which the torque acts.'),step('Integrate constant torque','For constant torque the work equals torque times the cumulative angular displacement.','W = τΔθ','Whole revolutions still count toward supplied work.'),step('Check energy and power','Starting at rest, all work goes into rotational kinetic energy.','W = ½Iω²; P = τω','Power grows as the flywheel speeds up.')],answer:(s,m)=>target(`Starting from rest, find work supplied by τ = ${s.torque} N m through the displayed θ = ${fmt(m.theta)} rad at t = ${fmt(s.time)} s.`,m.work,'J',[`W = τθ = ${s.torque} × ${fmt(m.theta)} = ${fmt(m.work)} J.`,`Check: ½Iω² = ${fmt(.5*m.I*m.omega*m.omega)} J.`])}
};
for(const [id,c] of Object.entries(rotationConfigs))add(id,{...c,compute:s=>{const m=c.calc(s);m.readouts=[read(m.label,m.value,m.unit),read('Angle',m.theta,'rad')];return m;},scene:(s,m,t)=>{
 const arrow=(...args)=>K.arrow(...args).replace('<path ','<path stroke="'+K.color('paper')+'" stroke-width="2.5" stroke-linejoin="round" paint-order="stroke fill" ');
 let out=rotorScene(s,id==='10.3'?{...m,caption:'Acceleration arrows use different fixed scales (at left); do not compare their drawn lengths.'}:m,t,id==='10.7'||id==='10.8'?4:20);
 if(id==='10.3'){
  const p=diskPoint(480,280,150*s.radius/.8,m.theta),a=m.theta;
  const xr=p[0]-14*Math.cos(a),yr=p[1]+14*Math.sin(a),xt=p[0]+14*Math.cos(a),yt=p[1]-14*Math.sin(a);
  if(m.ar>0)out+=K.line(p[0],p[1],xr,yr,'line',1)+arrow(xr,yr,xr-3*m.ar*Math.cos(a),yr+3*m.ar*Math.sin(a));
  if(m.at>0)out+=K.line(p[0],p[1],xt,yt,'line',1)+arrow(xt,yt,xt-300*m.at*Math.sin(a),yt-300*m.at*Math.cos(a),'wire');
  out+=text(150,155,`a_r = ${fmt(m.ar)} m/s²`,'coral')+text(150,185,`a_t = ${fmt(m.at)} m/s²`,'wire')+text(150,220,'Radial: 3 px/(m/s²)','muted',13)+text(150,245,'Tangential: 300 px/(m/s²)','muted',13)+text(150,280,'Origins shifted off rim marker','muted',12);
 }
 if(id==='10.7'||id==='10.8'){
  const x=480+150*s.radius/.8,F=id==='10.7'?s.force:s.torque/s.radius,scale=id==='10.7'?50:20;
  out+=arrow(x,280,x,280-scale*F)+text(780,170,id==='10.8'?'Equivalent rim force F = τ/R':'Tangential force at fixed rim','ink',15)+text(780,200,`F = ${fmt(F)} N`)+text(780,230,`τ = ${fmt(id==='10.7'?m.torque:s.torque)} N m`)+text(780,260,`Force: ${scale} px/N`,'muted',13);
 }
 return out;
},target:c.answer,sourceNote:`Inspected §${id} definitions, equations and rigid-body diagrams; original fixed-axis ideal apparatus.`,animation:{label:'Turn wheel',kind:'physical',duration:4}});
R['10.3'].steps[2].visual='The dark tangential acceleration arrow is perpendicular to the coral inward acceleration. Their different fixed scales are labeled; compare numerical components, not drawn lengths.';
add('10.5',{title:'Move the axle of a uniform rod',intro:'Shift a parallel axle away from the center of mass and compare the growing rotational inertia.',controls:[slider('mass','Rod mass',1,6,.5,3,'kg'),slider('length','Rod length',1,4,.1,2,'m'),slider('offset','Axle distance from center',0,1.5,.1,.5,'m')],compute:s=>({I:s.mass*s.length*s.length/12+s.mass*s.offset*s.offset,readouts:[read('Rod inertia about axle',s.mass*s.length*s.length/12+s.mass*s.offset*s.offset,'kg m²')]}),scene:(s,m)=>box(480-70*s.length,255,140*s.length,40,'aqua')+K.circle(480,275,7,'coral')+K.line(480+140*s.offset,150,480+140*s.offset,380,'wire',4)+text(480,220,'Center of mass')+text(480+140*s.offset,410,'Parallel axle')+K.line(480,345,480+140*s.offset,345,'coral',3)+text(480,110,`I = ${fmt(m.I)} kg m²`)+note('Thin uniform rod; axle perpendicular to the page. Offset may lie outside the rod.'),steps:[step('Start at the center','Integrate r² dm over the uniform rod about its center.','I_cm = ML²/12','The center is marked in coral.'),step('Move the axis','The parallel-axis theorem accounts for the additional distance of all mass elements.','I = I_cm + Mh²','The vertical axle shifts while the rod’s center stays fixed.'),step('Check the minimum','Because Mh² is nonnegative, the center-of-mass axis has the smallest inertia.','I ≥ I_cm','Return the offset to zero to recover the central-axis value.')],target:(s,m)=>target(`Uniform thin rod: M = ${s.mass} kg, L = ${s.length} m. Find I about a parallel axis h = ${s.offset} m from its center.`,m.I,'kg m²',[`I_cm = ML²/12 = ${fmt(s.mass*s.length*s.length/12)} kg m².`,`I = I_cm + Mh² = ${fmt(m.I)} kg m².`]),animation:{label:'Inspect axle',kind:'construction',duration:6},sourceNote:'Inspected §10.5 rod inertia and parallel-axis theorem; massless offset axle, rigid rod.'});
function torqueModel(id,angularMomentum=false){add(id,{title:angularMomentum?'Measure a passing particle’s angular momentum':'Find a force’s turning effect',intro:angularMomentum?'Angular momentum depends on the perpendicular distance between the origin and the line of motion.':'The same force can create different torque when its direction or application radius changes.',controls:angularMomentum?[slider('mass','Particle mass',1,5,.5,2,'kg'),slider('speed','Particle speed',.5,3,.25,2,'m/s'),slider('offset','Height above origin',-1.5,1.5,.1,.8,'m')]:[slider('radius','Lever length',.3,2,.1,1,'m'),slider('force','Force magnitude',1,10,.5,5,'N'),slider('angle','Force angle from lever',-90,90,5,45,'°')],compute:s=>angularMomentum?{L:-s.mass*s.speed*s.offset,readouts:[read('Signed angular momentum',-s.mass*s.speed*s.offset,'kg m²/s')]}:{tau:s.radius*s.force*Math.sin(rad(s.angle)),readouts:[read('Signed torque',s.radius*s.force*Math.sin(rad(s.angle)),'N m')]},scene:(s,m,t)=>{if(angularMomentum){const x=230+55*s.speed*t,y=300-80*s.offset;return K.circle(480,300,8,'wire')+K.line(100,y,870,y,'line')+K.circle(x,y,16+3*s.mass)+K.arrow(x,y,x+35*s.speed,y)+K.line(480,300,x,y,'aqua')+K.line(480,300,480,y,'coral',3)+text(760,420,`L_z = ${fmt(m.L)}`)+note('Rightward motion; positive z points out of the page. Motion above the origin gives negative L_z.');}const x=280+200*s.radius,y=300,a=rad(s.angle);return K.circle(280,300,12,'wire')+K.line(280,300,x,y,'wire',13)+K.arrow(x,y,x+16*s.force*Math.cos(a),y-16*s.force*Math.sin(a))+text(480,100,`τ_z = ${fmt(m.tau)} N m`)+text(480,415,`Perpendicular lever arm = ${fmt(s.radius*Math.sin(a))} m`)+note('Lever held for measurement; positive torque is counterclockwise.');},steps:angularMomentum?[step('Choose the origin','Angular momentum is measured about a specified point.','L = r × p','The gray dot fixes the origin.'),step('Find the perpendicular offset','Only momentum perpendicular to r contributes.','L_z = −bmv','A rightward particle above the origin produces clockwise angular momentum.'),step('Check the line of motion','If the line passes through the origin, angular momentum about that origin is zero.','b = 0 ⇒ L_z = 0','Slide the trajectory through the gray dot.')]:[step('Choose the pivot','Distance is measured from the fixed axle to the application point.','τ = r × F','The dark dot is the pivot and the rod is the position vector.'),step('Resolve the force','The parallel component cannot twist the rod about its pivot.','F_perpendicular = F sin φ','The coral force arrow tilts relative to the rod.'),step('Keep the sign','Counterclockwise torque is positive; reversing the perpendicular component reverses torque.','τ_z = rF sin φ','At zero angle the line of action passes through the pivot.')],target:(s,m)=>angularMomentum?target(`Right-moving particle: m=${s.mass} kg, v=${s.speed} m/s, line y=${s.offset} m relative to origin. Find signed L_z.`,m.L,'kg m²/s',[`r × p gives L_z = −y p_x.`,`L_z = −(${s.offset})(${s.mass})(${s.speed}) = ${fmt(m.L)} kg m²/s.`]):target(`Find signed torque about the axle: r=${s.radius} m, F=${s.force} N, force ${s.angle}° counterclockwise from rightward lever.`,m.tau,'N m',[`τ_z = rF sin φ = ${s.radius} × ${s.force} × sin(${s.angle}°).`,`τ_z = ${fmt(m.tau)} N m.`]),animation:{label:angularMomentum?'Move particle':'Inspect torque',kind:angularMomentum?'physical':'construction',duration:angularMomentum?2:6},sourceNote:`Inspected §${id} ${angularMomentum?'particle angular-momentum cross product':'torque cross product and moment arm'}; original planar signed example.`});}
torqueModel('10.6');torqueModel('11.4');torqueModel('11.5',true);
add('11.1',{title:'Roll a wheel without slipping',intro:'A marked point traces a cycloid. The point touching the ground is momentarily at rest because translation cancels rotation there.',controls:[slider('radius','Wheel radius',.2,.7,.05,.4,'m'),slider('speed','Center speed',.2,1,.1,.6,'m/s')],compute:s=>({omega:s.speed/s.radius,x:s.speed*s.time,theta:s.speed*s.time/s.radius,readouts:[read('Angular speed',s.speed/s.radius,'rad/s'),read('Top-point speed',2*s.speed,'m/s'),read('Contact-point speed',0,'m/s')]}),scene:(s,m)=>{const r=100*s.radius,cx=180+100*m.x,cy=370-r,p=diskPoint(cx,cy,r,-pi/2-m.theta);return K.line(80,370,880,370)+wheel(cx,cy,r,-m.theta)+K.circle(...p,9,'aqua')+K.arrow(cx,cy,cx+90*s.speed,cy)+K.arrow(cx,cy-r,cx+180*s.speed,cy-r,'aqua')+text(480,100,'Ground contact: v_translation + v_rotation = 0')+note('No slipping, fixed 100 px per metre; aqua point is attached to the rim.');},steps:[step('Add translation','The whole wheel’s center moves right at v_cm.','v_translation = v_cm','The center arrow shows the forward speed.'),step('Add rotation','Rotation moves the bottom rim backward relative to the center at ωR.','v_rotation,bottom = −ωR','The marked rim point rotates clockwise while translating.'),step('Enforce no slip','The bottom point must be instantaneously at rest relative to the stationary floor.','v_cm = ωR','At the top the same velocities add to 2v_cm.')],target:(s,m)=>target(`A wheel rolls without slipping at ${s.speed} m/s with radius ${s.radius} m. Find angular-speed magnitude.`,m.omega,'rad/s',[`No slip requires v_cm = ωR.`,`ω = ${s.speed}/${s.radius} = ${fmt(m.omega)} rad/s.`]),animation:{label:'Roll wheel',kind:'physical',duration:5},sourceNote:'Inspected §11.1 rolling as translation plus rotation and contact/top-point velocities; ideal no slip.'});
add('11.2',{title:'Roll different bodies down a ramp',intro:'Gravity provides the energy while static friction supplies the torque. More rotational inertia leaves less acceleration for translation.',controls:[slider('angle','Ramp angle',5,25,1,15,'°'),slider('radius','Rolling radius',.2,.6,.05,.4,'m'),select('beta','Mass distribution',.5,[[.4,'Solid sphere'],[.5,'Solid cylinder'],[1,'Thin hoop']])],compute:s=>{const a=g*Math.sin(rad(s.angle))/(1+s.beta),v=a*s.time,x=.5*a*s.time*s.time;return{a,v,x,theta:x/s.radius,readouts:[read('Down-ramp acceleration',a,'m/s²'),read('Translation speed',v,'m/s'),read('Rotation/translation energy ratio',s.beta)]};},scene:(s,m)=>{const a=rad(s.angle),r=50*s.radius,cx=170+50*m.x*Math.cos(a)+r*Math.sin(a),cy=150+60*Math.tan(a)+50*m.x*Math.sin(a)-r*Math.cos(a);return K.line(110,150,720,150+610*Math.tan(a),'wire',5)+wheel(cx,cy,r,-m.theta)+K.arrow(cx,cy,cx+80*Math.sin(a),cy+80*Math.cos(a))+K.arrow(cx,cy+r,cx-60*Math.cos(a),cy+r-60*Math.sin(a),'aqua')+text(480,80,'Gravity drives; static friction provides the turning torque')+note('No slipping, rigid body and sufficient static friction; arrows schematic; fixed distance scale.');},steps:[step('Resolve gravity','The downhill component of weight accelerates the center. Static friction acts uphill.','Mg sin θ − f = Ma','The aqua friction arrow points up the ramp.'),step('Use torque and no slip','Friction turns the body and links angular acceleration to translational acceleration.','fR = Iα; a = αR','A larger β means more torque is needed for the same a.'),step('Solve the coupled motion','Combine both Newton equations using I = βMR².','a = g sin θ/(1 + β)','Radius changes the spin but cancels from the downhill acceleration.')],target:(s,m)=>target(`Find down-ramp acceleration for θ=${s.angle}°, I=${s.beta}MR², no slipping, g=9.81 m/s².`,m.a,'m/s²',[`a = g sin θ/(1 + β).`,`a = 9.81 sin(${s.angle}°)/(1 + ${s.beta}) = ${fmt(m.a)} m/s².`]),animation:{label:'Release body',kind:'physical',duration:2},sourceNote:'Inspected §11.2 force/torque equations for rolling on an incline; no-slip and static friction assumed.'});
add('11.3',{title:'Unwind a descending yo-yo',intro:'A yo-yo falls more slowly than a freely falling particle because tension must spin the body as the string unwinds.',controls:[slider('mass','Yo-yo mass',.1,.5,.05,.25,'kg'),slider('radius','Outer radius',.03,.08,.005,.05,'m'),slider('ratio','Axle/outer radius',.2,.8,.05,.4)],compute:s=>{const a=g/(1+.5/(s.ratio*s.ratio)),T=s.mass*(g-a);return{a,T,y:.5*a*s.time*s.time,theta:.5*a*s.time*s.time/(s.radius*s.ratio),readouts:[read('Downward acceleration',a,'m/s²'),read('String tension',T,'N')]};},scene:(s,m)=>{const r=50+350*s.radius,cx=480,cy=155+30*m.y;return K.line(cx-r*s.ratio,75,cx-r*s.ratio,cy,'wire',3)+K.line(400,75,560,75,'wire',6)+wheel(cx,cy,r,-m.theta)+K.circle(cx,cy,r*s.ratio,'aqua',.3)+K.arrow(cx+95,cy,cx+95,cy+Math.min(80,18*s.mass*g))+K.arrow(cx-95,cy,cx-95,cy-Math.min(80,18*m.T),'aqua')+text(750,140,'Tension spins the axle')+note('Uniform solid-disk inertia ½MR²; massless string, no slip, no axle losses.');},steps:[step('Balance translation','Weight acts down; string tension acts up.','Mg − T = Ma','Both forces are visible beside the yo-yo.'),step('Balance rotation','Tension acts at axle radius r, not outer radius R.','Tr = Iα; a = αr','The aqua axle changes with the radius ratio.'),step('Eliminate tension','The rotational inertia reduces the fall acceleration.','a = g/(1 + I/(Mr²))','A small axle requires more angular acceleration per metre of descent.')],target:(s,m)=>target(`For a uniform-disk yo-yo, axle ratio r/R=${s.ratio}; g=9.81 m/s². Find downward acceleration, ignoring losses.`,m.a,'m/s²',[`I/(Mr²) = 0.5/(r/R)² = ${fmt(.5/(s.ratio*s.ratio))}.`,`a = g/(1 + I/(Mr²)) = ${fmt(m.a)} m/s².`]),animation:{label:'Drop yo-yo',kind:'physical',duration:1.5},sourceNote:'Inspected §11.3 yo-yo acceleration with axle radius and tension; solid-disk teaching body.'});
function angular(id,conserve){add(id,{title:conserve?'Pull masses inward on a spinning platform':id==='11.7'?'Build the angular momentum of a rigid rotor':'Change angular momentum with torque',intro:conserve?'With zero external torque, pulling the masses inward makes the platform spin faster while angular momentum stays constant.':'A symmetric two-mass rotor gives a clear rotational inertia. Applied torque changes its angular momentum.',controls:[slider('mass','Each point mass',.5,3,.25,1,'kg'),slider('radius','Initial radius',.3,1,.05,.7,'m'),...(conserve?[slider('ratio','Final/initial radius',.3,1,.05,.6)]:[slider('torque','External torque',0,1,.1,.4,'N m')]),slider('omega','Initial angular speed',.5,3,.25,1,'rad/s')],compute:s=>{const I0=2*s.mass*s.radius*s.radius,q=conserve?1-(1-s.ratio)*Math.min(1,s.time/4):1,r=s.radius*q,I=2*s.mass*r*r,L=I0*s.omega+(conserve?0:s.torque*s.time),w=L/I;let theta;if(conserve){const b=(1-s.ratio)/4,t=Math.min(s.time,4);theta=b===0?s.omega*s.time:s.omega/b*(1/(1-b*t)-1)+(s.time>4?(s.time-4)*s.omega/(s.ratio*s.ratio):0);}else theta=s.omega*s.time+.5*s.torque/I*s.time*s.time;return{I0,I,r,L,w,theta,readouts:[read('Rotational inertia',I,'kg m²'),read('Angular momentum',L,'kg m²/s'),read('Angular speed',w,'rad/s')]};},scene:(s,m)=>{const r=160*m.r,a=m.theta,p1=diskPoint(480,280,r,a),p2=diskPoint(480,280,r,a+pi);return K.circle(480,280,170,'line',.15)+K.line(...p1,...p2,'wire',4)+K.circle(...p1,13+5*s.mass)+K.circle(...p2,13+5*s.mass,'aqua')+K.circle(480,280,8,'wire')+text(480,80,conserve?'No external torque: L stays constant':'External torque changes L')+(!conserve?K.arrow(730,310,730,310-90*s.torque):K.arrow(p1[0],p1[1],480+(p1[0]-480)*.6,280+(p1[1]-280)*.6))+note(conserve?'Point masses moved inward by an internal actuator. Its work increases kinetic energy.':'Massless rod and symmetric point masses; axle fixed; signed CCW rotation.');},steps:conserve?[step('Isolate the rotor','Internal radial pulls exert no net external torque about the axle.','L_initial = L_final','The radial inward arrow represents the internal pull.'),step('Change inertia','The masses remain equal but their distance from the axle decreases.','I = 2mr²','The apparatus visibly shrinks as the masses move inward.'),step('Predict the spin','Reducing inertia requires increasing angular speed to preserve L.','ω_final = ω_initial (r_initial/r_final)²','Extra kinetic energy comes from the actuator, not from nowhere.')]:[step('Add the particles','Each point mass contributes mr² about the fixed central axle.','I = 2mr²','The two masses lie at equal opposite radii.'),step('Relate momentum and speed','For this symmetric rotor the angular momentum is aligned with the axle.','L_z = Iω','Changing the radius changes inertia quadratically.'),step('Apply angular Newton’s law','A constant external torque changes angular momentum linearly in time.','L_z(t) = Iω₀ + τt','The rotor speeds up when the external torque is positive.')],target:(s,m)=>conserve?target(`At the final contracted radius r_f=${s.ratio}r_i, find angular speed. Initial ω=${s.omega} rad/s; no external torque.`,s.omega/(s.ratio*s.ratio),'rad/s',[`I_f/I_i = (${s.ratio})².`,`ω_f = I_iω_i/I_f = ${fmt(s.omega/(s.ratio*s.ratio))} rad/s.`]):target(`Find angular momentum at t=${fmt(s.time)} s for two masses ${s.mass} kg each at r=${s.radius} m, initial ω=${s.omega} rad/s, applied τ=${s.torque} N m.`,m.L,'kg m²/s',[`I = 2mr² = ${fmt(m.I)} kg m².`,`L = Iω₀ + τt = ${fmt(m.L)} kg m²/s.`]),animation:{label:conserve?'Pull inward':'Spin rotor',kind:'physical',duration:4},sourceNote:`Inspected §${id} ${conserve?'zero-torque conservation of angular momentum':'angular momentum and angular Newton law'}; symmetric two-point-mass model.`});}
angular('11.6',false);angular('11.7',false);angular('11.8',true);
add('11.9',{title:'Precess a fast-spinning gyroscope',intro:'Gravity changes the direction of a rapidly spinning rotor’s angular momentum. It precesses about the support instead of simply falling.',controls:[slider('mass','Rotor mass',.5,3,.25,1,'kg'),slider('radius','Rotor radius',.05,.2,.01,.1,'m'),slider('arm','Support-to-center distance',.1,.4,.025,.2,'m'),slider('omega','Spin angular speed',200,600,25,400,'rad/s')],compute:s=>{const I=.5*s.mass*s.radius*s.radius,L=I*s.omega,O=s.mass*g*s.arm/L;return{I,L,O,phi:O*s.time,readouts:[read('Precession rate',O,'rad/s'),read('Spin angular momentum',L,'kg m²/s')]};},scene:(s,m)=>{const x=480+450*s.arm*Math.cos(m.phi),y=270-150*s.arm*Math.sin(m.phi),r=45+200*s.radius;return K.line(480,300,480,420,'wire',8)+K.line(480,300,x,y,'wire',7)+wheel(x,y,r,s.omega*s.time)+K.arrow(x,y,x,y+90*s.mass/3)+K.arrow(480,300,480+(x-480)*1.4,300+(y-300)*1.4,'aqua')+K.path('M270,300A210,70 0 1 0 690,300A210,70 0 1 0 270,300','line',2)+text(480,95,`Ω = ${fmt(m.O)} rad/s`)+note('Fast-spin, steady-precession approximation. Perspective and rotor-spin display are schematic.');},steps:[step('Find gravity’s torque','The center of mass lies a distance r from the support, so gravity supplies a torque.','τ = Mgr','The coral downward arrow is the rotor’s weight.'),step('Find spin angular momentum','For a uniform disk, spin inertia is half mass times radius squared.','L = Iω_spin; I = ½MR²','The aqua axle arrow represents spin angular momentum.'),step('Turn the momentum vector','For steady horizontal precession the rate is torque divided by angular momentum.','Ω = Mgr/(Iω_spin)','Faster spin slows precession. Nutation and slow-spin falling are excluded.')],target:(s,m)=>target(`Fast uniform-disk gyroscope: M=${s.mass} kg, R=${s.radius} m, support arm ${s.arm} m, spin ${s.omega} rad/s. Find steady precession rate using g=9.81.`,m.O,'rad/s',[`I = ½MR² = ${fmt(m.I)} kg m²; L = Iω = ${fmt(m.L)} kg m²/s.`,`Ω = Mgr/L = ${fmt(m.O)} rad/s.`]),animation:{label:'Precess',kind:'physical',duration:5},sourceNote:'Inspected §11.9 gyroscope torque and Ω=Mgr/(Iω); fast-spin approximation, original schematic perspective.'});
// Static equilibrium and elastic deformation.
for(const id of ['12.1','12.2'])add(id,{title:id==='12.1'?'Balance force and torque on a beam':'Place a load on a supported beam',intro:id==='12.1'?'A beam at rest needs both zero net force and zero net torque. See the support forces adjust as the load moves.':'A uniform beam supports its own weight plus a movable load. Torque balance finds the reactions before force balance checks them.',controls:[slider('load','Hanging mass',1,8,.5,4,'kg'),slider('position','Load distance from left',.3,3.7,.1,2.5,'m'),slider('beam','Uniform beam mass',0,5,.5,2,'kg')],compute:s=>{const B=g*(s.load*s.position+s.beam*2)/4,A=g*(s.load+s.beam)-B;return{A,B,readouts:[read('Left upward reaction',A,'N'),read('Right upward reaction',B,'N')]};},scene:(s,m,t,stage)=>{const x=200+140*s.position;return box(200,255,560,20,'aqua')+K.path('M180,340L200,285L220,340Z','wire',3)+K.path('M740,340L760,285L780,340Z','wire',3)+K.line(x,275,x,320)+box(x-20,320,40,20+5*s.load,'coral')+K.arrow(200,250,200,250-.8*m.A,'aqua')+K.arrow(760,250,760,250-.8*m.B,'aqua')+K.arrow(480,285,480,285+7*s.beam)+text(200,120,`R_A = ${fmt(m.A)} N`)+text(760,120,`R_B = ${fmt(m.B)} N`)+(stage===1?K.circle(200,275,30,'coral',.3):'')+note('Rigid 4 m uniform beam, ideal pin/roller supports, downward gravity. Arrow scale 0.8 px/N.');},steps:[step('List external forces','The load and beam weights act down; both supports push up.','R_A + R_B = (m_load + m_beam)g','The beam’s own weight acts at its center.'),step('Take moments about the left support','The unknown left reaction has zero moment arm about its own support.','4R_B = m_load g x + m_beam g(2)','The highlighted left support is the torque origin.'),step('Check both conditions','Use vertical force balance for the other reaction and verify both supports remain positive.','ΣF_y = 0; Στ_z = 0','Moving the load right transfers reaction from the left support to the right.')],target:(s,m)=>target(`Find right reaction of a 4 m uniform beam: beam mass ${s.beam} kg, point load ${s.load} kg at ${s.position} m from left, g=9.81.`,m.B,'N',[`Take moments about left: 4R_B = (${s.load})(9.81)(${s.position}) + (${s.beam})(9.81)(2).`,`R_B = ${fmt(m.B)} N.`]),animation:{label:'Inspect equilibrium',kind:'construction',duration:6},sourceNote:`Inspected §${id} simultaneous force/torque equilibrium and supported-beam diagrams; original simple-support geometry.`});
add('12.3',{title:'Stretch a rod elastically',intro:'Apply a tensile force and inspect the extension. Cross-sectional area reduces stress, while a larger Young modulus makes the rod stiffer.',controls:[slider('force','Tensile force',100,1000,50,500,'N'),slider('area','Cross-sectional area',5,20,.5,10,'mm²'),slider('length','Original length',.5,2,.1,1,'m'),slider('E','Young modulus',50,200,10,100,'GPa')],compute:s=>({stress:s.force/(s.area*1e-6),extension:s.force*s.length/(s.area*1e-6*s.E*1e9),readouts:[read('Stress',s.force/s.area,'MPa'),read('Extension',s.force*s.length/(s.area*1e-6*s.E*1e9)*1000,'mm')]}),scene:(s,m,t,stage)=>{const y=270,h=10+4*Math.sqrt(s.area),L=190*s.length,ext=m.extension*15000;return K.line(150,150,150,360,'wire',8)+box(150,y-h/2,L,h,'aqua')+box(150+L,y-h/2,ext,h,'coral')+K.arrow(150+L+ext,y,150+L+ext+80*s.force/1000,y)+K.line(150+L,180,150+L,360,'line',2)+text(480,100,`Extension: ${fmt(m.extension*1000)} mm`)+text(600,400,'Coral segment shows ΔL × 15,000')+(stage===1?K.circle(150+L/2,y,h+10,'coral',.15):'')+note('Linear elastic small-strain model. Length and extension use different explicitly labeled display scales.');},steps:[step('Convert to stress','The same force spreads over the cross-sectional area.','σ = F/A','A larger area makes the rod thicker and reduces stress.'),step('Relate stress and strain','Young modulus is the ratio of tensile stress to relative extension.','σ = E ε; ε = ΔL/L','The coral extension is exaggerated and labeled.'),step('Solve the extension','Longer rods extend more under the same stress, while stiffer materials extend less.','ΔL = FL/(AE)','The gray line marks the unstretched end.')],target:(s,m)=>target(`Find extension in mm: F=${s.force} N, A=${s.area} mm², L=${s.length} m, E=${s.E} GPa.`,m.extension*1000,'mm',[`A = ${s.area}×10⁻⁶ m²; E = ${s.E}×10⁹ Pa.`,`ΔL = FL/(AE) = ${fmt(m.extension)} m = ${fmt(m.extension*1000)} mm.`]),animation:{label:'Inspect strain',kind:'construction',duration:6},sourceNote:'Inspected §12.3 tensile stress/strain and Young modulus; uniform linear-elastic rod, extension exaggerated.'});
const GE=3.986004418e14,RE=6.371e6;
for(const id of ['13.1','13.3','13.4','13.5']){const interior=id==='13.4',potential=id==='13.5';add(id,{title:{'13.1':'Attract a test mass toward Earth','13.3':'Raise a gravity probe above Earth','13.4':'Lower a probe inside a uniform Earth','13.5':'Climb Earth’s gravitational energy well'}[id],intro:interior?'Inside a uniform sphere, only the enclosed mass contributes to the net inward field. Gravity decreases linearly toward the center.':potential?'Moving a test mass outward raises its potential energy toward zero. Negative potential energy marks a gravitationally bound position.':'Move a test mass farther from Earth and see the inverse-square gravitational pull weaken.',controls:[slider('r','Distance from Earth center',interior?0:1,interior?1:4,.05,interior?.6:1.5,'Earth radii'),slider('mass','Test mass',1,10,.5,4,'kg'),slider('factor','Earth mass multiplier',.5,2,.1,1)],compute:s=>{const r=s.r*RE,field=interior?GE*s.factor*s.r/(RE*RE):GE*s.factor/(r*r),U=interior?0:-GE*s.factor*s.mass/r;return{field,F:s.mass*field,U,r,readouts:[read('Inward gravitational acceleration',field,'m/s²'),read(potential?'Potential energy':'Inward force',potential?U:s.mass*field,potential?'J':'N')]};},scene:(s,m,t,stage)=>{const x=220+140*s.r;return K.circle(220,280,140,'aqua',.22)+(interior?K.circle(220,280,140*s.r,'coral',.12):'')+K.circle(220,280,6,'wire')+K.circle(x,280,8+2*s.mass)+K.arrow(x,280,x-Math.min(145,9*m.field),280)+K.line(220,310,x,310,'line')+text(220,95,interior?'Uniform-density Earth model':'Spherical Earth, exterior field')+text(610,390,potential?`U = ${fmt(m.U/1e6)} MJ`:`g = ${fmt(m.field)} m/s²`)+(stage===1?K.circle(x,280,25,'coral',.18):'')+note(interior?'Enclosed mass ∝ r³; outside shells cancel. Radius uses a fixed scale.':'Earth radius fixed; test-mass size and force arrow use schematic scales.');},steps:interior?[step('Use spherical symmetry','Outer spherical shells make zero net contribution at an interior point.','M_enclosed = M(r/R)³','The coral sphere shows only the enclosed mass.'),step('Apply the inverse-square law','Insert the enclosed mass, not the full Earth mass.','g(r) = GM_enclosed/r² = GMr/R³','The inward force weakens toward the center.'),step('Check both limits','The field is zero at the exact center and continuous at the surface.','g(0) = 0; g(R) = GM/R²','The center and surface give independent sanity checks.')]:potential?[step('Choose the zero','Set gravitational potential energy to zero at infinite separation.','U(∞) = 0','The probe is bound at any finite radius.'),step('Integrate the force','The inverse-square attraction integrates to an inverse-distance potential.','U(r) = −GMm/r','Moving outward makes the negative value closer to zero.'),step('Relate work to energy','A slow outward lift requires positive external work.','W_external = ΔU','The attractive force still points inward while the probe is lifted.')]:[step('Measure from the center','The spherical mass acts as if concentrated at its center for an exterior point.','r = (r/R_E) R_E','Distance is not measured from the surface.'),step('Use the inverse square','Doubling the distance from the center quarters the field.','g = GM/r²','The force arrow shrinks as the probe moves outward.'),step('Distinguish force and field','The test mass changes force but not its own free-fall acceleration.','F = mg','Increasing test mass grows the particle and force, while g stays fixed.')],target:(s,m)=>target(interior?`Uniform Earth: mass multiplier ${s.factor}, radius R_E=6.371×10⁶ m, GM_E=3.986004418×10¹⁴ m³/s². Find g at r=${s.r}R_E.`:`Find ${potential?'U':'g'} at r=${s.r}R_E, Earth mass multiplier ${s.factor}, test mass ${s.mass} kg; R_E=6.371×10⁶ m and GM_E=3.986004418×10¹⁴ m³/s².`,potential?m.U:m.field,potential?'J':'m/s²',interior?[`g = GM r/R³ = (GM/R²)(r/R).`,`g = ${fmt(m.field)} m/s² inward.`]:potential?[`U = −GMm/r.`,`U = ${fmt(m.U)} J.`]:[`r = ${fmt(m.r)} m.`,`g = GM/r² = ${fmt(m.field)} m/s² inward.`]),animation:{label:'Inspect gravity',kind:'construction',duration:6},sourceNote:`Inspected §${id} ${interior?'shell theorem and uniform-sphere interior field':potential?'gravitational potential energy':'Newtonian inverse-square gravitation'}; spherical Earth ${interior?'uniform-density idealization':'outside-field approximation'}, test mass negligible.`});}
add('13.2',{title:'Balance attraction from two masses',intro:'Gravitational forces add as vectors. Between two sources the pulls oppose; a larger mass or shorter distance dominates.',controls:[slider('left','Left source mass',1,5,.5,3,'10¹² kg'),slider('right','Right source mass',1,5,.5,2,'10¹² kg'),slider('x','Probe position',1,5,.1,3,'km')],compute:s=>{const FL=6.6743e-11*s.left*1e12/(s.x*1000)**2,FR=6.6743e-11*s.right*1e12/((6-s.x)*1000)**2;return{FL,FR,net:FR-FL,readouts:[read('Left acceleration',-FL,'m/s²'),read('Right acceleration',FR,'m/s²'),read('Net signed acceleration',FR-FL,'m/s²')]};},scene:(s,m,t,stage)=>{const x=180+100*s.x;return K.circle(180,290,22+7*s.left,'aqua')+K.circle(780,290,22+7*s.right,'aqua')+K.circle(x,290,11)+K.arrow(x,220,x-Math.min(170,m.FL*3000000),220)+K.arrow(x,250,x+Math.min(170,m.FR*3000000),250,'aqua')+text(180,390,'x = 0 km')+text(780,390,'x = 6 km')+text(480,110,`a_net = ${fmt(m.net)} m/s²`)+(stage===2?K.arrow(x,320,x+Math.max(-160,Math.min(160,m.net*3000000)),320):'')+note('Point sources fixed 6 km apart. Positive is right. Force arrow lengths use a capped schematic scale.');},steps:[step('Calculate each attraction','Each source pulls the probe toward itself.','a_left = −GM_left/x²','The left contribution points left.'),step('Calculate the right attraction','Distance to the right source is 6 km minus the probe coordinate.','a_right = GM_right/(D − x)²','The right contribution points right.'),step('Add with signs','Magnitudes do not simply add when directions oppose.','a_net = a_right + a_left','The resultant arrow points toward the stronger contribution.')],target:(s,m)=>target(`Sources at 0 and 6 km have masses ${s.left}×10¹² and ${s.right}×10¹² kg. Find signed acceleration at x=${s.x} km, positive right, G=6.6743×10⁻¹¹ SI.`,m.net,'m/s²',[`a_left = −${fmt(m.FL)}, a_right = ${fmt(m.FR)} m/s².`,`a_net = ${fmt(m.net)} m/s².`]),animation:{label:'Inspect contributions',kind:'construction',duration:6},sourceNote:'Inspected §13.2 superposition of vector gravitational forces; fixed point sources, test-particle limit.'});
function eccentricAnomaly(mean,e){let E=mean;for(let n=0;n<14;n++)E-=(E-e*Math.sin(E)-mean)/(1-e*Math.cos(E));return E;}
add('13.6',{title:'Sweep equal areas in an elliptical orbit',intro:'The planet moves faster near the Sun. Equal time steps sweep equal areas because its angular momentum is conserved.',controls:[slider('a','Semimajor axis',.7,1.8,.1,1,'AU'),slider('e','Orbital eccentricity',0,.7,.05,.4)],compute:s=>{const period=s.a**1.5,M=TAU*s.time/period,E=eccentricAnomaly(M,s.e),r=s.a*(1-s.e*Math.cos(E));return{E,r,x:s.a*(Math.cos(E)-s.e),y:s.a*Math.sqrt(1-s.e*s.e)*Math.sin(E),period,readouts:[read('Orbital period',period,'years'),read('Sun–planet distance',r,'AU'),read('Area swept per year',pi*s.a*s.a*Math.sqrt(1-s.e*s.e)/period,'AU²/year')]};},scene:(s,m)=>{const sc=90,cx=480-sc*s.a*s.e,cy=285,rx=sc*s.a,ry=rx*Math.sqrt(1-s.e*s.e),px=480+sc*m.x,py=285-sc*m.y;return K.path(`M${cx+rx},${cy}A${rx},${ry} 0 1 0 ${cx-rx},${cy}A${rx},${ry} 0 1 0 ${cx+rx},${cy}`,'line',2)+K.circle(480,285,18,'coral')+K.line(480,285,px,py,'aqua',3)+K.circle(px,py,10,'aqua')+text(480,75,'Sun at focus • clock in Earth years')+note('Kepler two-body ellipse, one-solar-mass Sun. No perturbations; 90 px per AU.');},steps:[step('Use the focus','The Sun lies at a focus of the ellipse, not at its geometric center.','r = a(1 − e cos E)','The orbital ellipse shifts relative to the fixed Sun.'),step('Advance equal times','Mean anomaly grows uniformly; eccentric anomaly solves Kepler’s equation.','E − e sin E = 2πt/T','The moving planet advances nonuniformly along the ellipse.'),step('Connect the laws','Conserved angular momentum gives equal swept area; the period depends on a, not e.','T² = a³; dA/dt = constant','Changing eccentricity redistributes speed without changing the period at fixed a.')],target:(s,m)=>target(`A negligible-mass planet orbits a one-solar-mass Sun with a=${s.a} AU and e=${s.e}. Find its period in Earth years, using T²=a³.`,m.period,'years',[`T = √(a³) = a^(3/2).`,`T = ${fmt(m.period)} years; eccentricity does not enter this period law.`]),animation:{label:'Orbit planet',kind:'physical',duration:3,unit:'years'},sourceNote:'Inspected §13.6 Kepler ellipse/focus, equal areas and T²∝a³ diagrams; standard AU/year solar normalization.'});
add('13.7',{title:'Place a satellite in a circular orbit',intro:'At a larger orbital radius a satellite moves more slowly yet has greater total mechanical energy. Watch a full orbit with a model clock in minutes.',controls:[slider('r','Orbital radius',1.1,3,.1,1.5,'Earth radii'),slider('mass','Satellite mass',100,1000,100,400,'kg')],compute:s=>{const r=s.r*RE,v=Math.sqrt(GE/r),T=TAU*r/v,theta=TAU*s.time*60/T;return{r,v,T,theta,E:-GE*s.mass/(2*r),readouts:[read('Orbital speed',v,'m/s'),read('Period',T/60,'min'),read('Total orbital energy',-GE*s.mass/(2*r),'J')]};},scene:(s,m)=>{const r=65*s.r,p=diskPoint(480,285,r,m.theta),w=12+4*Math.cbrt(s.mass/100);return K.circle(480,285,65,'aqua',.3)+K.path(`M${480+r},285A${r},${r} 0 1 0 ${480-r},285A${r},${r} 0 1 0 ${480+r},285`,'line',2)+box(p[0]-w,p[1]-w*.6,2*w,1.2*w,'coral')+box(p[0]-28,p[1]-4,12,8,'aqua')+box(p[0]+16,p[1]-4,12,8,'aqua')+K.arrow(p[0],p[1],p[0]-Math.sin(m.theta)*m.v/100,p[1]-Math.cos(m.theta)*m.v/100,'aqua')+text(480,55,'Circular orbit • negligible satellite gravity')+note('Earth drawn to fixed radial scale; satellite hardware exaggerated for visibility.');},steps:[step('Supply centripetal force','Gravity points inward and turns the velocity without changing its speed.','GMm/r² = mv²/r','The satellite moves tangentially around the fixed Earth.'),step('Solve the orbital speed','Satellite mass cancels; radius sets the required circular speed.','v = √(GM/r)','A larger orbit has a slower angular motion.'),step('Add the energies','For a circular orbit, kinetic energy is half the magnitude of the negative potential energy.','E = K + U = −GMm/(2r)','A less negative total energy corresponds to a higher orbit.')],target:(s,m)=>target(`Find circular orbital speed at r=${s.r}R_E; R_E=6.371×10⁶ m, GM_E=3.986004418×10¹⁴ m³/s².`,m.v,'m/s',[`r = ${fmt(m.r)} m.`,`v = √(GM/r) = ${fmt(m.v)} m/s.`]),animation:{label:'Orbit satellite',kind:'physical',duration:180,unit:'min'},sourceNote:'Inspected §13.7 circular satellite energy, orbital speed and period; spherical Earth, drag-free orbit.'});
add('13.8',{title:'Compare gravity with an accelerating rocket',intro:'A scale inside a closed laboratory cannot locally distinguish standing in uniform gravity from accelerating upward in empty space.',controls:[slider('mass','Person mass',40,100,5,65,'kg'),slider('accel','Gravity / rocket acceleration',2,12,.5,9.5,'m/s²')],compute:s=>({N:s.mass*s.accel,readouts:[read('Scale reading in gravity',s.mass*s.accel,'N'),read('Scale reading in accelerating rocket',s.mass*s.accel,'N')]}),scene:(s,m,t,stage)=>{const shift=stage===2?20:0;return box(150,140,240,270)+box(570,140-shift,240,270)+box(220,350,100,25,'coral')+box(640,350-shift,100,25,'coral')+K.circle(270,235,15,'aqua')+K.line(270,250,270,340,'aqua',12)+K.circle(690,235-shift,15,'aqua')+K.line(690,250-shift,690,340-shift,'aqua',12)+K.arrow(350,320,350,320-.1*m.N)+K.arrow(770,320,770,320-.1*m.N)+text(270,100,'Standing on a planet')+text(690,100,'Accelerating in space')+text(480,450,`Both scales read ${fmt(m.N)} N`)+note('Local uniform-field equivalence only; tidal effects and spacetime curvature are outside this model.');},steps:[step('Read the planet scale','At rest in gravity, the normal force balances gravitational weight.','N = mg','The left floor pushes upward on the person.'),step('Read the rocket scale','In empty space an upward normal force provides the person’s acceleration.','N = ma','The right floor pushes upward with the same force when a = g.'),step('Apply local equivalence','Within a sufficiently small laboratory these mechanical measurements agree.','a = g ⇒ N_rocket = N_planet','This illustrates the equivalence principle, not a global identity of gravitational fields.')],target:(s,m)=>target(`A ${s.mass} kg person accelerates upward at ${s.accel} m/s² in a gravity-free rocket. Find the scale force.`,m.N,'N',[`Only the upward normal force accelerates the person.`,`N = ma = ${s.mass} × ${s.accel} = ${fmt(m.N)} N.`]),animation:{label:'Compare laboratories',kind:'construction',duration:6},sourceNote:'Inspected §13.8 Einstein/gravitation and equivalence discussion; original local accelerating-lab demonstration, no GR trajectory integration.'});
add('14.1',{title:'Press on a fluid piston',intro:'Pressure is force per area. Spread the same force over a broader piston and the fluid pressure drops.',controls:[slider('force','Piston force',10,100,5,50,'N'),slider('area','Piston area',10,100,5,40,'cm²')],compute:s=>({p:s.force/(s.area*1e-4),readouts:[read('Added fluid pressure',s.force/(s.area*1e-4)/1000,'kPa')]}),scene:(s,m,t,stage)=>{const w=30*Math.sqrt(s.area),x=480-w/2;return box(x,180,w,220,'aqua')+K.line(x,180,x+w,180,'wire',10)+K.arrow(480,180-s.force,480,180)+Array.from({length:8},(_,i)=>K.circle(x+20+(w-40)*(i+.5)/8,300,3+Math.min(10,m.p/5000),'coral',stage===2?.7:.3)).join('')+text(480,445,`Δp = ${fmt(m.p/1000)} kPa`)+note('Piston and fluid at rest. Added pressure excludes the common atmospheric background.');},steps:[step('Identify the contact area','The applied force is distributed over the piston face.','A = area normal to force','Changing area changes the actual piston width.'),step('Define pressure','A fluid at rest transmits normal force per area, not directed shear.','Δp = F/A','The downward force arrow loads the fluid.'),step('Keep units consistent','Convert square centimetres into square metres before dividing.','1 cm² = 10⁻⁴ m²','The coral dots indicate pressure magnitude schematically, not density.')],target:(s,m)=>target(`A piston has force ${s.force} N over area ${s.area} cm². Find the added pressure in kPa.`,m.p/1000,'kPa',[`A = ${s.area}×10⁻⁴ m².`,`Δp = F/A = ${fmt(m.p/1000)} kPa.`]),animation:{label:'Inspect pressure',kind:'construction',duration:6},sourceNote:'Inspected §14.1 pressure as normal force/area and density; piston teaching model isolates pressure.'});
add('14.2',{title:'Lower a pressure probe into a tank',intro:'Pressure rises with depth because the fluid above must be supported. Changing density changes the pressure gradient.',controls:[slider('depth','Probe depth',.2,3,.1,1.5,'m'),slider('rho','Fluid density',600,1400,50,1000,'kg/m³')],compute:s=>({p:s.rho*g*s.depth,readouts:[read('Gauge pressure',s.rho*g*s.depth/1000,'kPa')]}),scene:(s,m,t,stage)=>{const y=150+85*s.depth;return box(230,150,500,300,'aqua')+K.line(230,150,730,150,'aqua',4)+K.line(620,150,620,y,'wire',2)+K.circle(620,y,12,'coral')+K.arrow(540,y,540+Math.min(60,m.p/500),y)+text(480,135,'Open surface: p = p_atmosphere')+text(480,100,`Depth ${s.depth} m • gauge pressure ${fmt(m.p/1000)} kPa`)+(stage===1?box(595,150,50,y-150,'coral'):'')+note('Uniform incompressible fluid at rest; gauge pressure is zero at the free surface.');},steps:[step('Choose a fluid column','A column of height h has mass ρAh and weight ρAhg.','Weight = ρAhg','The highlighted column lies above the probe.'),step('Balance vertical forces','The pressure difference supports the weight; cross-sectional area cancels.','(p − p₀)A = ρAhg','The gauge probe reads pressure relative to the open surface.'),step('Predict depth dependence','In a constant-density fluid pressure rises linearly with depth.','p_gauge = ρgh','The tank’s width does not enter the result.')],target:(s,m)=>target(`Find gauge pressure at depth ${s.depth} m in fluid density ${s.rho} kg/m³, g=9.81.`,m.p/1000,'kPa',[`p_gauge = ρgh = ${s.rho} × 9.81 × ${s.depth} Pa.`,`p_gauge = ${fmt(m.p/1000)} kPa.`]),animation:{label:'Inspect column',kind:'construction',duration:6},sourceNote:'Inspected §14.2 hydrostatic pressure derivation and fluid-column balance; constant density and g.'});
add('14.3',{title:'Read a U-tube manometer',intro:'The gas pushes one liquid surface down and the other up. Their vertical height difference measures gauge pressure.',controls:[slider('pressure','Gas gauge pressure',.5,12,.5,4,'kPa'),slider('rho','Manometer liquid density',800,1400,50,1000,'kg/m³')],compute:s=>({h:s.pressure*1000/(s.rho*g),readouts:[read('Liquid height difference',s.pressure*1000/(s.rho*g),'m')]}),scene:(s,m,t,stage)=>{const dh=m.h*100,y1=260+dh/2,y2=260-dh/2;return K.path('M300,130L300,370Q480,440 660,370L660,130','wire',12)+K.path(`M300,${y1}L300,370Q480,440 660,370L660,${y2}`,'aqua',30)+box(240,85,120,50)+text(300,115,'Gas')+text(660,90,'Open to air')+K.line(350,y1,720,y1,'line')+K.line(600,y2,720,y2,'line')+K.arrow(720,y1,720,y2)+text(800,260,`h = ${fmt(m.h)} m`)+(stage===2?K.circle(480,400,25,'coral',.3):'')+note('Same liquid in both arms, gas density neglected. Difference h, not one arm’s displacement.');},steps:[step('Compare the surfaces','Gas pressure exceeds atmospheric pressure and depresses the left arm.','p_gas > p_atm','The free surfaces separate vertically.'),step('Follow a level through liquid','Pressure is the same at equal depth in the connected stationary liquid.','p_gas − p_atm = ρgh','The bottom of the U connects both liquid columns.'),step('Use the full difference','Both arms move, but the formula uses the entire surface-height difference.','h = p_gauge/(ρg)','The vertical coral arrow spans both levels.')],target:(s,m)=>target(`Manometer gas gauge pressure ${s.pressure} kPa, liquid density ${s.rho} kg/m³, g=9.81. Find surface-height difference h.`,m.h,'m',[`Convert Δp = ${s.pressure*1000} Pa.`,`h = Δp/(ρg) = ${fmt(m.h)} m.`]),animation:{label:'Read manometer',kind:'construction',duration:6},sourceNote:'Inspected §14.3 open-tube manometer hydrostatic height relation; gas-density and capillary corrections neglected.'});
add('14.4',{title:'Lift a load with linked hydraulic pistons',intro:'Equal pressure links the two pistons. The larger piston gains force but travels a shorter distance, preserving ideal work.',controls:[slider('A1','Small piston area',5,15,1,10,'cm²'),slider('ratio','Large/small area ratio',2,6,.5,4),slider('force','Input force',20,100,5,50,'N'),slider('stroke','Input displacement',.05,.3,.025,.2,'m')],compute:s=>({F2:s.force*s.ratio,x2:s.stroke/s.ratio,readouts:[read('Output force',s.force*s.ratio,'N'),read('Output stroke',s.stroke/s.ratio,'m'),read('Ideal input work',s.force*s.stroke,'J')]}),scene:(s,m,t)=>{const f=t/6,w1=18*Math.sqrt(s.A1),w2=w1*Math.sqrt(s.ratio),y1=230+200*s.stroke*f,y2=230-200*m.x2*f;return K.path('M250,280L250,400L680,400L680,280','aqua',25)+box(250-w1/2,y1,w1,400-y1,'aqua')+box(680-w2/2,y2,w2,400-y2,'aqua')+K.line(250-w1/2,y1,250+w1/2,y1,'wire',10)+K.line(680-w2/2,y2,680+w2/2,y2,'wire',10)+K.arrow(250,120,250,120+s.force)+K.arrow(680,y2,680,y2-Math.min(130,m.F2/4),'coral')+text(250,80,'Input piston')+text(680,80,'Output piston')+note('Same elevation, incompressible liquid, massless pistons, no losses. Construction shows the chosen full stroke.');},steps:[step('Transmit pressure','Pascal’s principle transfers the added pressure through the confined fluid.','F₁/A₁ = F₂/A₂','The two connected liquid columns share the added pressure.'),step('Trade force for distance','The displaced liquid volume must match on both sides.','A₁x₁ = A₂x₂','The wide piston rises less than the narrow piston descends.'),step('Check work','A hydraulic press multiplies force without multiplying energy.','F₁x₁ = F₂x₂','The output work equals the input work in this ideal model.')],target:(s,m)=>target(`Hydraulic press: input force ${s.force} N, output/input area ratio ${s.ratio}. Find output force at equal elevation, ignoring losses.`,m.F2,'N',[`Equal pressure gives F₂ = F₁(A₂/A₁).`,`F₂ = ${s.force} × ${s.ratio} = ${fmt(m.F2)} N.`]),animation:{label:'Push piston',kind:'construction',duration:6},sourceNote:'Inspected §14.4 Pascal hydraulic-lever geometry, force multiplication and work relation; ideal equal-height pistons.'});
add('14.5',{title:'Immerse a block and measure buoyancy',intro:'Buoyancy depends on displaced fluid volume, not directly on block weight. Compare upward buoyancy with downward weight as the block enters the water.',controls:[slider('volume','Block volume',1,6,.5,3,'L'),slider('fraction','Submerged fraction',0,1,.05,.6),slider('rho','Fluid density',800,1200,50,1000,'kg/m³'),slider('block','Block density',500,1500,100,900,'kg/m³')],compute:s=>({B:s.rho*g*s.volume*.001*s.fraction,W:s.block*g*s.volume*.001,readouts:[read('Buoyant force',s.rho*g*s.volume*.001*s.fraction,'N'),read('Block weight',s.block*g*s.volume*.001,'N'),read('Holding force upward',s.block*g*s.volume*.001-s.rho*g*s.volume*.001*s.fraction,'N')]}),scene:(s,m,t,stage)=>{const h=55+10*s.volume,w=h,y=250-h*(1-s.fraction);return box(200,250,560,190,'aqua')+box(480-w/2,y,w,h,'coral')+K.line(200,250,760,250,'aqua',3)+K.arrow(600,y+h/2,600,y+h/2-Math.min(150,m.B*2),'aqua')+K.arrow(370,y+h/2,370,y+h/2+Math.min(150,m.W*2))+text(480,90,`Displaced volume = ${fmt(s.volume*s.fraction)} L`)+(stage===1?box(480-w/2,250,w,h*s.fraction,'aqua'):'')+note('Block held at selected depth. External holding force may be upward or downward; no free-float dynamics claimed.');},steps:[step('Find displaced volume','For a straight-sided block, submerged volume is the chosen fraction times total volume.','V_displaced = f V','The part below the aqua surface displaces liquid.'),step('Apply Archimedes’ principle','The pressure difference produces an upward force equal to the displaced liquid’s weight.','F_B = ρ_fluid g V_displaced','The aqua force grows as more of the block is immersed.'),step('Compare with weight','Weight depends on block density. Any imbalance is supplied by the holding mechanism.','F_hold + F_B − W = 0','A freely floating block would settle where buoyancy equals weight.')],target:(s,m)=>target(`Block volume ${s.volume} L, fraction submerged ${s.fraction}, fluid density ${s.rho} kg/m³. Find buoyancy using g=9.81.`,m.B,'N',[`V_displaced = ${s.volume*.001*s.fraction} m³.`,`F_B = ρgV = ${fmt(m.B)} N.`]),animation:{label:'Inspect displacement',kind:'construction',duration:6},sourceNote:'Inspected §14.5 Archimedes buoyancy and apparent weight; held straight-sided block, no buoyant-motion integration.'});
function pipe(id,bernoulli){add(id,{title:bernoulli?'Trade pressure for flow speed in a constriction':'Keep fluid volume flowing through a narrowing pipe',intro:bernoulli?'At the same height, faster flow in a narrower section has lower pressure. Watch parcels accelerate through the throat.':'Incompressibility requires the same volume per second through both sections. Narrowing the pipe increases the fluid speed.',controls:[slider('A1','Wide cross-sectional area',15,30,1,20,'cm²'),slider('A2','Throat cross-sectional area',4,14,1,8,'cm²'),slider('Q','Volume flow rate',.2,2,.1,1,'L/s')],compute:s=>{const v1=10*s.Q/s.A1,v2=10*s.Q/s.A2,p2=50000+.5*1000*(v1*v1-v2*v2);return{v1,v2,p2,readouts:[read('Wide-section speed',v1,'m/s'),read('Throat speed',v2,'m/s'),read(bernoulli?'Throat gauge pressure':'Flow at both sections',bernoulli?p2/1000:s.Q,bernoulli?'kPa':'L/s')]};},scene:(s,m,t)=>{const h1=24*Math.sqrt(s.A1),h2=24*Math.sqrt(s.A2),L=3,V1=s.A1*1e-4*L,V2=s.A2*1e-4*L,Q=s.Q*.001;let out=K.path(`M140,${280-h1/2}L440,${280-h1/2}L520,${280-h2/2}L820,${280-h2/2}L820,${280+h2/2}L520,${280+h2/2}L440,${280+h1/2}L140,${280+h1/2}Z`,'wire',4,'surface');for(let i=0;i<16;i++){const V=(Q*t+(V1+V2)*i/16)%(V1+V2),x=V<V1?140+300*V/V1:520+300*(V-V1)/V2;out+=K.circle(x,280+(i%3-1)*12,4,'aqua');}out+=K.arrow(250,280,250+55*m.v1,280)+K.arrow(620,280,620+30*m.v2,280)+text(280,380,`v₁ = ${fmt(m.v1)} m/s`)+text(680,380,`v₂ = ${fmt(m.v2)} m/s`);if(bernoulli)out+=K.line(280,280,280,80,'aqua',5)+K.line(680,280,680,280-.004*m.p2,'aqua',5)+text(480,420,`p₁ = 50 kPa • p₂ = ${fmt(m.p2/1000)} kPa`);return out+note('Round-pipe diameter ∝ √area. Equal 3 m straight sections; connector motion schematic; water, same elevation.');},steps:[step('Conserve volume','A steady incompressible flow carries the same volume per time through each section.','Q = A₁v₁ = A₂v₂','The narrower pipe requires parcels to move faster.'),step(bernoulli?'Conserve mechanical energy':'Convert the units',bernoulli?'At equal height, pressure energy decreases as kinetic energy per volume increases.':'Cross-sectional area and volume flow must use consistent units.',bernoulli?'p₁ + ½ρv₁² = p₂ + ½ρv₂²':'1 L/s = 10⁻³ m³/s; 1 cm² = 10⁻⁴ m²','The coral arrows compare speeds on fixed scales.'),step(bernoulli?'Predict pressure drop':'Check each section',bernoulli?'The aqua columns represent pressure head: lower pressure supports a shorter column.':'Different speeds do not imply different volume rates because the areas differ.',bernoulli?'p₂ = p₁ + ½ρ(v₁² − v₂²)':'v₂/v₁ = A₁/A₂','The common flow rate remains the same at both ends.')],target:(s,m)=>target(bernoulli?`Water density 1000 kg/m³, same elevation, p₁=50 kPa. A₁=${s.A1} cm², A₂=${s.A2} cm², Q=${s.Q} L/s. Find p₂ in kPa.`:`Find speed in the throat: A₂=${s.A2} cm², steady flow Q=${s.Q} L/s.`,bernoulli?m.p2/1000:m.v2,bernoulli?'kPa':'m/s',bernoulli?[`v₁=${fmt(m.v1)} m/s; v₂=${fmt(m.v2)} m/s.`,`p₂ = 50000 + 500(v₁² − v₂²) = ${fmt(m.p2/1000)} kPa.`]:[`Q=${s.Q*.001} m³/s; A₂=${s.A2*.0001} m².`,`v₂=Q/A₂=${fmt(m.v2)} m/s.`]),animation:{label:'Run flow',kind:'carriers',duration:10},sourceNote:`Inspected §${id} ${bernoulli?'Bernoulli pressure/kinetic-energy balance':'continuity and tube-of-flow figures'}; steady incompressible inviscid flow, equal elevations. Fluid markers are schematic through the connector.`});}
