function oscillator(id){const damp=id==='15.5',forced=id==='15.6',energy=id==='15.2';add(id,{title:forced?'Drive a spring mass near resonance':damp?'Watch a damped spring mass lose amplitude':energy?'Exchange spring energy and kinetic energy':'Move a mass in simple harmonic motion',intro:forced?'The driver transfers the most energy when its frequency matches the oscillator’s natural response. Damping keeps the steady amplitude finite.':damp?'A viscous damper removes mechanical energy. The mass still oscillates, but its envelope shrinks over time.':'The spring pulls toward equilibrium. Displacement and velocity evolve together rather than changing only a number.',controls:forced?[slider('mass','Mass',1,3,.25,1,'kg'),slider('drive','Drive angular frequency',1,6,.1,3,'rad/s'),slider('b','Damping coefficient',1,3,.25,1.5,'kg/s'),slider('force','Driving force amplitude',.2,1,.1,.6,'N')]:[slider('mass','Mass',1,4,.25,2,'kg'),slider('k','Spring stiffness',8,32,1,16,'N/m'),slider('A','Initial displacement',.05,.3,.025,.2,'m'),...(damp?[slider('b','Damping coefficient',.2,2,.2,.8,'kg/s')]:[])],compute:s=>{const k=forced?16:s.k,w0=Math.sqrt(k/s.mass),gamma=damp?s.b/(2*s.mass):0,wd=Math.sqrt(w0*w0-gamma*gamma);let x,v,A=s.A,phase=0;if(forced){A=s.force/Math.hypot(k-s.mass*s.drive*s.drive,s.b*s.drive);phase=Math.atan2(s.b*s.drive,k-s.mass*s.drive*s.drive);x=A*Math.cos(s.drive*s.time-phase);v=-s.drive*A*Math.sin(s.drive*s.time-phase);}else if(damp){x=A*Math.exp(-gamma*s.time)*(Math.cos(wd*s.time)+gamma/wd*Math.sin(wd*s.time));v=-A*Math.exp(-gamma*s.time)*(w0*w0/wd)*Math.sin(wd*s.time);}else{x=A*Math.cos(w0*s.time);v=-A*w0*Math.sin(w0*s.time);}return{x,v,A,w0,wd,gamma,phase,k,K:.5*s.mass*v*v,U:.5*k*x*x,readouts:[read('Displacement',x,'m'),read('Velocity',v,'m/s'),read(forced?'Steady amplitude':'Mechanical energy',forced?A:.5*s.mass*v*v+.5*k*x*x,forced?'m':'J')]};},scene:(s,m,t)=>{const x=480+260*m.x,y=300;let out=K.line(120,220,120,350,'wire',8)+K.line(100,350,860,350)+spring(120,x-30,y)+box(x-30,y-32,60+7*s.mass,60,'coral')+K.line(480,200,480,370,'line',2)+K.arrow(x,200,x-10*m.k*m.x,200)+K.arrow(x,390,x+60*m.v,390,'aqua')+text(480,95,forced?'Steady-state response; k = 16 N/m':`k = ${s.k} N/m`) +text(720,265,`x = ${fmt(m.x)} m`);if(damp||forced)out+=K.line(120,250,x-50,250,'aqua',7)+box(x-80,235,40,30,'aqua');if(energy||damp)out+=box(180,135,180*m.K,18,'coral')+box(500,135,180*m.U,18,'aqua')+text(230,175,`K = ${fmt(m.K)} J`)+text(560,175,`U = ${fmt(m.U)} J`);if(forced)out+=K.arrow(x,245,x+80*s.force*Math.cos(s.drive*t),245)+text(720,420,`Amplitude ${fmt(m.A)} m`);return out+note(forced?'Ideal linear oscillator in established steady state; no startup transient. Position scale 260 px/m.':'Released from x=A with v=0. Position scale 260 px/m; arrows show signed force and velocity.');},steps:forced?[step('Combine three forces','The spring restores, the damper removes energy and the driver supplies periodic force.','m x″ + bx′ + kx = F₀ cos(ω_d t)','The coral driver arrow changes direction with the forcing.'),step('Find the steady response','After transients decay, motion occurs at the driver frequency with a phase lag.','A = F₀/√((k − mω_d²)² + (bω_d)²)','Change drive frequency and observe the actual travel amplitude.'),step('Explain resonance','Near the natural frequency, the elastic and inertial terms nearly cancel and damping limits amplitude.','ω₀ = √(k/m)','The force–motion phase also changes through resonance.')]:damp?[step('Add a drag force','The damper resists velocity and dissipates energy.','F_damping = −bv','The aqua dashpot opposes motion.'),step('Reduce the envelope','The underdamped frequency is slightly below the natural frequency.','γ = b/(2m); ω_d = √(k/m − γ²)','Successive excursions shrink toward equilibrium.'),step('Use the initial conditions','This solution starts at x=A and zero velocity, which requires a sine correction.','x = A e^(−γt)[cos(ω_d t) + (γ/ω_d)sin(ω_d t)]','The initial position is fixed while damping changes its later trajectory.')]:[step('Identify the restoring force','The spring force is opposite to displacement from equilibrium.','F = −kx','The coral force points toward the gray equilibrium line.'),step('Apply Newton’s law','Restoring force proportional to displacement produces sinusoidal motion.','ω = √(k/m); x = A cos(ωt)','The mass starts at its positive turning point.'),step(energy?'Track energy exchange':'Compare velocity and displacement',energy?'The spring stores energy at turning points; kinetic energy is largest at equilibrium.':'Velocity is the time derivative of position and is largest near equilibrium.',energy?'E = ½mv² + ½kx² = ½kA²':'v = −Aω sin(ωt)','The aqua velocity arrow vanishes at turning points.')],target:(s,m)=>target(forced?`Find established steady amplitude for k=16 N/m, m=${s.mass} kg, b=${s.b} kg/s, F₀=${s.force} N, ω_d=${s.drive} rad/s.`:damp?`Find the damped angular frequency for m=${s.mass} kg, k=${s.k} N/m, b=${s.b} kg/s.`:energy?`A spring oscillator has k=${s.k} N/m and amplitude ${s.A} m. Find its total mechanical energy.`:`Find period for spring stiffness ${s.k} N/m and mass ${s.mass} kg.`,forced?m.A:damp?m.wd:energy?.5*s.k*s.A*s.A:TAU/m.w0,forced?'m':damp?'rad/s':energy?'J':'s',forced?[`A = F₀/√((k − mω_d²)² + (bω_d)²).`,`A = ${fmt(m.A)} m.`]:damp?[`γ = b/(2m) = ${fmt(m.gamma)} s⁻¹.`,`ω_d = √(k/m − γ²) = ${fmt(m.wd)} rad/s.`]:energy?[`E = ½kA².`,`E = ${fmt(.5*s.k*s.A*s.A)} J.`]:[`ω₀ = √(k/m) = ${fmt(m.w0)} rad/s.`,`T = 2π/ω₀ = ${fmt(TAU/m.w0)} s.`]),animation:{label:'Oscillate',kind:'physical',duration:10},sourceNote:`Inspected §${id} ${forced?'forced steady response and resonance':damp?'underdamped motion and energy decay':energy?'SHM kinetic/potential energy exchange':'SHM position, velocity and spring frequency'}; linear spring, ${forced?'steady-state sinusoidal drive':damp?'viscous underdamped regime':'frictionless oscillator'}.`});}
